function auto1v1CantarTruco(nivel) { netAuto1v1Accion({ tipo: "cantarTruco", valor: nivel }); }
function auto1v1SubirTruco(nivel) { netAuto1v1Accion({ tipo: "subirTruco", valor: nivel }); }
