/* Todas las ligas disponibles. LIGA = la liga activa (cambia según el club elegido) */
// Ligas seleccionables/visibles en los selectores (registro, amistoso, etc.).
// Brasil, Colombia, Ecuador y Venezuela ya NO aparecen como ligas: sus
// clubes solo salen para la Copa Libertadores.
const LIGAS = [LIGA_LPA, LIGA_LALIGA, LIGA_PREMIER, LIGA_SELECCIONES, LIGA_MUNDIAL2026];
// Ligas que existen SOLO para nutrir la Libertadores (no se muestran como liga).
const LIGAS_LIBERTADORES = [LIGA_BRASIL, LIGA_COLOMBIA, LIGA_ECUADOR, LIGA_VENEZUELA];
let LIGA = LIGA_LPA;

/* Agrupación regional del selector: clubes de Sudamérica, clubes de Europa, selecciones */
const REGIONES = [
  { key: "sudamerica", nombre: "CLUBES — SUDAMÉRICA" },
  { key: "europa", nombre: "CLUBES — EUROPA" },
  { key: "selecciones", nombre: "SELECCIONES NACIONALES" },
  { key: "mundial2026", nombre: "MUNDIAL 2026" }
];

/* ── Helpers multi-liga ── */
// Acá hubo dos veces un Set de escudos que se servían como .svg porque su
// .webp estaba mal. Las dos veces se resolvió arreglando el ASSET, no el
// código, y por eso hoy no hay Set: todo pasa por .webp.
//
// ⚠️ La lección, para que no haya una tercera: el .webp puede estar roto
// SIN dar 404, y entonces el fallback onerror de abajo no se entera. La
// segunda vez (9 ago, "talleres no carga el escudo") el archivo bajaba
// perfecto en 256x256 — lo que estaba mal era el contenido: magick había
// rasterizado el antialias contra un fondo opaco y se había comido el
// blanco, así que la "T" blanca de Talleres quedó negra sobre el azul
// marino del escudo y sobre la tarjeta negra desaparecía entero.
//
// Se reconvirtieron los 11 desviados con rsvg-convert (que sí respeta el
// alpha) + cwebp -q 88, y se verificaron los 134 pares svg/webp contando
// píxeles: negro = los 3 canales < 14, blanco = luminancia > 200. Todos
// coinciden con su fuente.
//
// Si volvés a tocar los escudos: NUNCA uses magick como renderer (fue el
// que los rompió las dos veces) y NUNCA valides por tamaño de archivo —
// los archivos rotos pesaban lo esperado. Compará píxeles contra el SVG.
function escudoDe(eq) {
  if (!eq) return "";
  const p = eq.escudo || ESCUDOS[eq.id] || "";
  return p.replace(/\.svg$/i, ".webp");
}
// Fallback en cadena para que NUNCA quede un "ícono roto":
//   1º falla el .webp  → reintenta con el .svg original
//   2º falla el .svg   → muestra un placeholder generado (disco con iniciales)
// El placeholder cubre los escudos que no existen como archivo (p.ej. varias
// selecciones del Mundial 2026, cuya carpeta no está).
function escudoFallback(img) {
  if (!img) return;
  if (!img.dataset.svgTry) {
    img.dataset.svgTry = "1";
    img.src = img.src.replace(/\.webp(\?.*)?$/i, ".svg");
    return;
  }
  if (!img.dataset.phTry) {
    img.dataset.phTry = "1";
    img.src = _escudoPlaceholder(img.alt || img.title || "");
  }
}

// Placeholder: disco oscuro con borde dorado y las iniciales del equipo.
function _escudoPlaceholder(nombre) {
  const palabras = String(nombre).replace(/[^\p{L}\s]/gu, "").trim().split(/\s+/).filter(Boolean);
  let ini;
  if (palabras.length >= 2) ini = palabras.map(w => w[0]).join("").slice(0, 3).toUpperCase();
  else ini = (palabras[0] || "?").slice(0, 3).toUpperCase();
  const svg = "<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 100 100'>" +
    "<circle cx='50' cy='50' r='46' fill='#243049' stroke='#c8a84b' stroke-width='3'/>" +
    "<text x='50' y='63' font-size='34' text-anchor='middle' fill='#ffe08a' " +
    "font-family='Arial,sans-serif' font-weight='700'>" + ini + "</text></svg>";
  return "data:image/svg+xml," + encodeURIComponent(svg);
}
function buscarEquipo(id) {
  // Busca en las ligas visibles y también en las de Libertadores (Brasil,
  // Colombia, Ecuador, Venezuela), que no se muestran pero sus clubes existen.
  const fuentes = (typeof LIGAS_LIBERTADORES !== "undefined") ? LIGAS.concat(LIGAS_LIBERTADORES) : LIGAS;
  for (const liga of fuentes) {
    const eq = liga.equipos.find(e => e.id === id);
    if (eq) return { liga, equipo: eq };
  }
  return null;
}

const EQ_KEY = "truco_equipo";
let equipoSel = null;   // equipo del jugador
let equipoRival = null; // equipo de la IA

// ── PARTIDO AMISTOSO — el jugador elige ambos equipos ──
let modoAmistoso   = false; // true mientras dura un partido amistoso
let amistosoEquipoJ = null; // equipo elegido para el jugador
let amistosoEquipoR = null; // equipo elegido para el rival

// ── MUNDIAL 2026 — rival fijado por el fixture/cuadro, no se sortea ──
let modoMundial = false; // true mientras dura un partido del Mundial (ver mundial.js)

// true mientras se RETOMA una partida guardada: evita que aplicarEquipoEnMesa
// re-sortee el rival (queremos respetar el equipo guardado).
let _retomando = false;

// true mientras se juega un partido de una COPA (Libertadores / Champions /
// Mundial de Clubes). El rival ya viene fijado por el cuadro, igual que el Mundial.
let modoCopa = false;

/* ── Apagado central de las banderas de modo ────────────────────────────
   El contexto de partida son banderas booleanas sueltas, y cada punto de
   entrada apagaba un subconjunto distinto: setName() limpiaba picadito y
   desafío pero NO modoAmistoso ni modoCopa, y retomarPartida() no limpiaba
   ninguna de las tres nuevas. Efecto: volvés al menú a mitad de un partido
   del Club o de una Copa, arrancás otra cosa, y esa bandera vieja sigue
   prendida — la Liga deja de registrar fechas EN SILENCIO, el rival no se
   re-sortea, y una victoria en un amistoso se anota como el partido de copa.

   Contrato: TODO punto de entrada de partida llama a esta función PRIMERO
   y después prende la suya (si tiene). Agregar un modo nuevo = apagarlo acá.
   S.modoOnline queda afuera a propósito: lo maneja el motor online, que no
   pasa por estos caminos. */
function limpiarBanderasDeModo() {
  modoAmistoso = false;
  modoMundial  = false;
  modoCopa     = false;
  if (typeof window !== "undefined") {
    window.modoPicadito      = false;
    window.modoDesafioDiario = false;
    window.modoCopaRapida    = false;
    window.modoMaraton       = false;
    window.modoHistoria      = false;
    window.modoTorneoRapido  = false;
    // El Torneo Rápido (extras.js) además lleva su propio estado de serie,
    // que no es una bandera: si no se cierra acá, arrancar otro modo dejaba
    // la serie viva y sus partidas se contaban como partidas del torneo.
    if (typeof window._torneoRapidoAbandonar === "function") window._torneoRapidoAbandonar();
  }
}
if (typeof window !== "undefined") window.limpiarBanderasDeModo = limpiarBanderasDeModo;

/* ── Selector agrupado: cada liga se arma como bloque .eq-cat colapsable ── */
function _crearEqCat(liga, abierta, onSelect, preseleccionadoId, onPreseleccion) {
  const sec = document.createElement("div");
  sec.className = "eq-cat" + (abierta ? " open" : "");

  // Encabezado de la categoría: logo + nombre + cantidad + flecha
  const hdr = document.createElement("div");
  hdr.className = "eq-cat-header";
  hdr.innerHTML =
    '<img class="eq-cat-logo" src="' + liga.logo + '" alt="' + liga.nombre + '" loading="lazy" decoding="async">' +
    '<div class="eq-cat-textos">' +
      '<span class="eq-cat-name">' + liga.nombre + '</span>' +
      '<span class="eq-cat-badge">' + liga.badge + ' · ' + liga.equipos.length + ' equipos</span>' +
    '</div>' +
    '<span class="eq-cat-arrow">▾</span>';
  hdr.onclick = () => sec.classList.toggle("open");

  // Grilla de equipos
  const grid = document.createElement("div");
  grid.className = "equipo-grid";

  liga.equipos.forEach(eq => {
    const card = document.createElement("div");
    card.className = "eq-card";
    card.title = eq.nombre + " · " + eq.sub;
    // loading="lazy": esta grilla se pinta 3 veces en DOMContentLoaded (Modo DT
    // + los dos lados del Amistoso) con las pantallas en display:none — sin lazy
    // eran ~1,4 MB de escudos antes de ver el menú. Mismo criterio que los
    // avatares de renderAvataresDT(). El escudo de la MESA sigue eager.
    card.innerHTML =
      '<img src="' + escudoDe(eq) + '" alt="' + eq.nombre + '" loading="lazy" decoding="async" onerror="escudoFallback(this)">' +
      '<span class="eq-nombre">' + eq.nombre + '</span>';
    card.onclick = (ev) => { ev.stopPropagation(); onSelect(eq, card); };
    grid.appendChild(card);
    if (preseleccionadoId === eq.id && onPreseleccion) onPreseleccion(eq, card);
  });

  sec.appendChild(hdr);
  sec.appendChild(grid);
  return sec;
}

/* Vuelca todas las LIGAS dentro de cont, agrupadas por región
   (Sudamérica / Europa / Selecciones) con su título de sección. */
function _renderRegiones(cont, abrirCriterio, onSelect, preseleccionadoId, onPreseleccion) {
  REGIONES.forEach((region, ridx) => {
    const ligasRegion = LIGAS.filter(l => (l.region || "sudamerica") === region.key);
    if (!ligasRegion.length) return;

    const wrap = document.createElement("div");
    wrap.className = "eq-region";

    const titulo = document.createElement("div");
    titulo.className = "eq-region-title";
    titulo.textContent = region.nombre;
    wrap.appendChild(titulo);

    ligasRegion.forEach((liga, idx) => {
      const abierta = abrirCriterio(liga, ridx === 0 && idx === 0);
      const sec = _crearEqCat(liga, abierta, (eq, card) => onSelect(eq, card, liga), preseleccionadoId, onPreseleccion);
      wrap.appendChild(sec);
    });

    cont.appendChild(wrap);
  });
}

/* ── Selector agrupado en la pantalla de registro ── */
function renderSelectorEquipos() {
  const cont = document.getElementById("eq-cat-container");
  if (!cont) return;
  cont.innerHTML = "";

  const guardado = localStorage.getItem(EQ_KEY);
  const seleccion = guardado ? buscarEquipo(guardado) : null;

  _renderRegiones(
    cont,
    (liga, esPrimera) => seleccion ? seleccion.liga.id === liga.id : esPrimera,
    (eq, card) => seleccionarEquipo(eq, card),
    guardado,
    (eq, card) => seleccionarEquipo(eq, card, true)
  );
}

function seleccionarEquipo(eq, card, silencioso) {
  equipoSel = eq;
  const encontrado = buscarEquipo(eq.id);
  if (encontrado) LIGA = encontrado.liga;
  lsSet(EQ_KEY, eq.id);
  document.querySelectorAll(".eq-card").forEach(c => c.classList.remove("activo"));
  if (card) card.classList.add("activo");
  const lbl = document.getElementById("equipo-elegido-lbl");
  if (lbl) lbl.textContent = "⚽ " + eq.nombre + " — " + eq.sub;
  if (!silencioso && typeof showToast === "function") {
    try { showToast("Elegiste " + eq.nombre + " 🏆"); } catch (e) {}
  }
}

/* ── Avatar del rival acorde a su club ─────────────────────────────────
   Si el club rival es uno de los 5 grandes, la IA usa ese hincha (antes
   podía salir un hincha de River dirigiendo a Belgrano). Índices según el
   orden de AVATARS en cartas.js. Clubes sin hincha propio: queda el
   sorteo de seleccionarRivalAleatorio(). */
const AVATAR_POR_CLUB = {
  river: 0, boca: 1, indep: 2, sanloren: 3, racing: 4,
  velez: 5, estudiantes: 6, newells: 7, rcental: 8,
  lanus: 9, banfield: 10, platense: 11, argjuniors: 12, talleres: 13,
  huracan: 14, instituto: 15, belgrano: 16, atucuman: 17, defensa: 18,
  gimnasia: 19,
  // 1 ago 2026: Unión y Colón — índices 20/21, agregados al final de
  // AVATARS (cartas.js) y AVATARES_DT (liga.js) para no correr los índices
  // ya existentes.
  union: 20, colon: 21,
  // Hinchas europeos
  "real-madrid": 22,
  "barcelona": 23,
  "atletico-madrid": 24,
  "arsenal": 25,
  "chelsea": 26,
  "liverpool": 27,
  "man-city": 28,
  "man-united": 29,
  "newcastle": 30,
  "tottenham": 31,
  // Hinchas europeos
  "sevilla": 32,
  "valencia": 33,
  "villarreal": 34,
  "real-betis": 35,
  "real-sociedad": 36,
  "athletic-club": 37,
  "espanyol": 38,
  "celta": 39,
  "deportivo": 40,
  "elche": 41,
  "getafe": 42,
  "oviedo": 43,
  "osasuna": 44,
  "mallorca": 45,
  "levante": 46,
  "girona": 47,
  "rayo-vallecano": 48,
  "aston-villa": 49,
  "bournemouth": 50,
  "brentford": 51,
  "brighton": 52,
  "coventry": 53,
  "crystal-palace": 54,
  "everton": 55,
  "fulham": 56,
  "hull": 57,
  "ipswich": 58,
  "leeds": 59,
  "nottm-forest": 60,
  "sunderland": 61,
};

/* Índice del hincha que le corresponde a un equipo.
   El club del Modo Carrera entra a la mesa con el id fantasma "__club__", que
   no está en AVATAR_POR_CLUB: por eso, dirigieras a quien dirigieras, el
   jugador se quedaba con el avatar por defecto (el emoji 🤠 de juego.js) al
   lado del escudo de Boca o del Real Madrid. _clubLanzarVs le cuelga el
   `realId` al equipo justamente para poder resolverlo acá. */
function _avatarIdxDeEquipo(eq) {
  if (!eq) return undefined;
  const idx = AVATAR_POR_CLUB[eq.id];
  if (idx !== undefined) return idx;
  if (eq.realId) return AVATAR_POR_CLUB[eq.realId];
  return undefined;
}

function sincronizarAvatarRivalConClub() {
  if (S.modoOnline || !equipoRival) return;
  // Al retomar no se re-sortea nada, pero si el rival guardado era el hincha
  // genérico hay que volver a ponerle el nombre del club (el slot arranca
  // cada carga con el nombre por defecto).
  if (_retomando) { _refrescarHinchaGenerico(); return; }
  const idx = _avatarIdxDeEquipo(equipoRival);
  if (idx === undefined || !AVATARS[idx]) {
    // Club sin hincha propio (LALIGA, Brasileirão, selecciones…): muñeco
    // misterioso pero el cartel dice el club de verdad — sin esto la
    // Champions mostraba "Hincha de Boca" dirigiendo a la Real Sociedad.
    AVATARS[AVATAR_GENERICO_IDX].name = "Hincha de " + equipoRival.nombre;
    S.idRival = AVATAR_GENERICO_IDX;
    if (typeof renderizarAvataresFijos === "function") renderizarAvataresFijos();
    return;
  }
  // Si matchear el club clonaría el avatar del jugador, gana el no-clon:
  // se respeta lo que ya sorteó seleccionarRivalAleatorio().
  if (AVATARS[idx].icon === S.avatarJugador) return;
  S.idRival = idx;
  if (typeof renderizarAvataresFijos === "function") renderizarAvataresFijos();
}

function _refrescarHinchaGenerico() {
  if (S.idRival === AVATAR_GENERICO_IDX && equipoRival)
    AVATARS[AVATAR_GENERICO_IDX].name = "Hincha de " + equipoRival.nombre;
}

/* ── El avatar del JUGADOR acorde a SU club ──────────────────────────
   Hermana de la de arriba, para el otro lado de la mesa. En Picadito el
   club se sortea pero el avatar quedaba clavado en el índice 0 (= hincha
   de River) para todo el mundo: en un juego cuya premisa entera es la
   identidad futbolera, cada partida arrancaba con el escudo de un club y
   la cara del hincha de otro. Y encima se contagiaba al rival — como el
   jugador "ocupaba" el avatar de River, la regla de no-clonar de arriba
   le dejaba al rival un hincha ajeno cuando le tocaba ese club (se veía
   "Hincha de Platense" con el escudo de River al lado).
   Solo aplica mientras el jugador no haya elegido avatar a mano: el
   elegido gana siempre, y por eso se mira `tg_avatar_dt` y no S. */
function sincronizarAvatarJugadorConClub() {
  if (S.modoOnline || !equipoSel) return;
  try { if (localStorage.getItem("tg_avatar_dt")) return; } catch (_) {}
  const idx = _avatarIdxDeEquipo(equipoSel);
  if (idx === undefined || !AVATARS[idx]) {
    // Club SIN hincha propio: europeo (LaLiga, Premier), brasileño, o el club
    // que el jugador fundó. Antes acá se salía sin hacer nada y quedaba el
    // avatar por defecto —el emoji 🤠— pegado al escudo del Real Madrid.
    // El hincha misterioso es la respuesta honesta: no tenemos su cara.
    // PENDIENTE DE ARTE: faltan hinchas europeos (y del club propio). Cuando
    // existan, alcanza con sumarlos a AVATARS/AVATARES_DT y mapearlos en
    // AVATAR_POR_CLUB — esta rama deja de usarse sola.
    if (typeof AVATAR_FALLBACK === "string") S.avatarJugador = AVATAR_FALLBACK;
    return;
  }
  // Se mueve el índice (así la grilla de Ajustes queda marcada en el mismo
  // hincha) Y TAMBIÉN S.avatarJugador: la primera versión solo movía el
  // índice, porque el único que llamaba era jugarYa() y ahí la línea
  // siguiente derivaba el avatar. Al llamarse ahora desde
  // aplicarEquipoEnMesa() —que corre en TODOS los modos— no hay nadie
  // después que lo derive, y el Partido Amistoso quedaba con el avatar
  // viejo sobre el escudo del club recién elegido.
  avatarSeleccionadoIdx = idx;
  S.avatarJugador = AVATARS[idx].icon;
}

// Revancha ("Nueva partida"): reiniciarPartida() re-sortea el avatar pero NO
// re-sortea el club rival → re-sincronizar en cada nuevoPartido. (En online
// y retomando la función sale sola al principio.)
if (typeof onJuego === "function") onJuego("nuevoPartido", sincronizarAvatarRivalConClub);

/* ── Aplicar escudos en la mesa ── */
function aplicarEquipoEnMesa() {
  // En Partido Amistoso y en el Mundial el rival ya está fijado: no se sortea.
  // Al RETOMAR una partida (_retomando) tampoco: el rival guardado se respeta.
  if (!modoAmistoso && !modoMundial && !modoCopa && !_retomando) {
    // MODO DT: el rival lo manda el FIXTURE, no el sorteo (7 ago 2026).
    // Antes se sorteaba al azar y ligaRegistrarPartido acreditaba igual
    // contra el par del fixture: jugabas contra Lanús —su escudo, su avatar,
    // su dificultad— y el toast y la tabla decían San Lorenzo. Seis fechas
    // seguidas medidas, seis rivales distintos entre lo jugado y lo anotado.
    // ligaRivalProgramado() ya existía, pero solo alimentaba el texto de
    // "📅 Próxima fecha": nada lo llevaba a la mesa. La Copa Rápida ya lo
    // había resuelto así; el torneo principal no.
    const delFixture = (typeof ligaRivalProgramado === "function") ? ligaRivalProgramado() : null;
    if (delFixture) {
      equipoRival = delFixture;
    } else {
      // Sin fixture (torneo terminado, o la fecha en la que descansás): se
      // sortea, como siempre. Ese partido no cuenta para la tabla.
      const pool = LIGA.equipos.filter(e => !equipoSel || e.id !== equipoSel.id);
      equipoRival = pool[Math.floor(Math.random() * pool.length)];
    }
  }
  // ORDEN IMPORTANTE: primero el jugador, después el rival. La regla de
  // no-clonar del rival compara contra S.avatarJugador, así que si el
  // jugador todavía no se sincronizó, el rival evita un avatar que en un
  // instante va a dejar de estar ocupado — y termina eligiendo mal.
  sincronizarAvatarJugadorConClub();
  sincronizarAvatarRivalConClub();

  const escJ = document.getElementById("player-escudo");
  if (escJ && equipoSel) {
    escJ.onerror = () => escudoFallback(escJ);
    escJ.src = escudoDe(equipoSel);
    escJ.style.display = "inline-block";
    escJ.title = equipoSel.nombre;
  }

  const escR = document.getElementById("rival-escudo");
  if (escR && equipoRival && equipoSel) {
    escR.onerror = () => escudoFallback(escR);
    escR.src = escudoDe(equipoRival);
    escR.style.display = "inline-block";
    escR.title = equipoRival.nombre;
  }

  if (equipoSel) {
    const el = document.getElementById("side-pbar-j");
    if (el) el.style.background = equipoSel.color;
  }

  // La dificultad de la IA depende del rival recién asignado
  if (typeof _renderDificultadIA === "function") _renderDificultadIA();
}

/* ══════════════════════════════════════════════════════════
   PARTIDO AMISTOSO — el jugador elige su equipo Y el del rival
   ══════════════════════════════════════════════════════════ */

/* Renderiza un selector de equipos (todas las ligas) dentro de
   cualquier contenedor, llamando a onSelect(equipo, card) al elegir. */
function _renderSelectorEquiposEn(contId, onSelect) {
  const cont = document.getElementById(contId);
  if (!cont) return;
  cont.innerHTML = "";

  _renderRegiones(
    cont,
    (liga, esPrimera) => esPrimera,
    (eq, card) => onSelect(eq, card)
  );
}

function _actualizarBotonAmistoso() {
  const btn = document.getElementById("btn-jugar-amistoso");
  if (btn) btn.disabled = !(amistosoEquipoJ && amistosoEquipoR);
}

/* Arma los dos selectores (mi equipo / rival) de la pantalla de amistoso */
function renderSelectorAmistoso() {
  _renderSelectorEquiposEn("eq-cat-container-amistoso-j", (eq, card) => {
    amistosoEquipoJ = eq;
    document.querySelectorAll("#eq-cat-container-amistoso-j .eq-card").forEach(c => c.classList.remove("activo"));
    if (card) card.classList.add("activo");
    const lbl = document.getElementById("amistoso-eq-j-lbl");
    if (lbl) lbl.textContent = "⚽ " + eq.nombre + " — " + eq.sub;
    _actualizarBotonAmistoso();
  });

  _renderSelectorEquiposEn("eq-cat-container-amistoso-r", (eq, card) => {
    amistosoEquipoR = eq;
    document.querySelectorAll("#eq-cat-container-amistoso-r .eq-card").forEach(c => c.classList.remove("activo"));
    if (card) card.classList.add("activo");
    const lbl = document.getElementById("amistoso-eq-r-lbl");
    if (lbl) lbl.textContent = "⚽ " + eq.nombre + " — " + eq.sub;
    _actualizarBotonAmistoso();
  });
}

/* Restaura el club/liga del Modo DT (por si quedaron pisados por un amistoso) */
function restaurarEquipoDT() {
  const guardado = localStorage.getItem(EQ_KEY);
  if (guardado) {
    const encontrado = buscarEquipo(guardado);
    if (encontrado) { equipoSel = encontrado.equipo; LIGA = encontrado.liga; }
  }
}

/* ══════════════════════════════════════════════════════════
   RETOMAR PARTIDA 1 JUGADOR
   Guarda el marcador del partido contra la IA entre manos
   (nunca a mitad de mano) y permite retomarlo si se cierra el
   juego. Solo modos "dt" y "amistoso"; online y mundial tienen
   su propio flujo y no se guardan acá.
   ══════════════════════════════════════════════════════════ */
const PARTIDA_KEY = "truco_partida_1p";

function _partidaModoTag() {
  if (typeof S !== "undefined" && S.modoOnline) return null;
  if (typeof modoMundial  !== "undefined" && modoMundial)  return null;
  if (typeof modoCopa     !== "undefined" && modoCopa)     return null;
  if (typeof modoAmistoso !== "undefined" && modoAmistoso) return "amistoso";
  // Historia/Maratón/Desafío del Día/Copa Rápida/Picadito viven en
  // window.modoX (ver limpiarBanderasDeModo más arriba). Antes caían todos
  // acá abajo en "dt" — retomarPartida() nunca podía volver a prender la
  // bandera real del modo, así que el capítulo/racha quedaba huérfano (sin
  // los hooks de fin de modo) y el partido se anotaba como fecha de Liga.
  if (typeof window !== "undefined") {
    if (window.modoHistoria)      return "historia";
    if (window.modoMaraton)       return "maraton";
    if (window.modoDesafioDiario) return "desafio_dia";
    if (window.modoCopaRapida)    return "copa_rapida";
    if (window.modoPicadito)      return "picadito";
  }
  return "dt";
}

function partidaGuardarSnapshot() {
  const tag = _partidaModoTag();
  if (!tag || S.juegoTerminado) return;
  const snap = {
    tag, ts: Date.now(),
    ptsJ: S.puntosJugador, ptsR: S.puntosRival, limite: S.limitePuntos,
    turnoMano: S.turnoMano, idRival: S.idRival,
    nombre: S.nombreJugador, avatar: S.avatarJugador,
    eqJ: equipoSel  ? equipoSel.id  : null,
    eqR: equipoRival ? equipoRival.id : null,
  };
  if (typeof lsSet === "function") lsSet(PARTIDA_KEY, JSON.stringify(snap));
  else { try { localStorage.setItem(PARTIDA_KEY, JSON.stringify(snap)); } catch (e) {} }
}

function partidaCargarSnapshot() {
  try { return JSON.parse(localStorage.getItem(PARTIDA_KEY)); } catch (e) { return null; }
}
function partidaBorrarSnapshot() {
  try { localStorage.removeItem(PARTIDA_KEY); } catch (e) {}
}

function retomarPartida() {
  const s = partidaCargarSnapshot();
  if (!s) return;

  S.modoOnline   = false;
  // Limpiar TODO primero y después prender solo lo que dice el snapshot:
  // antes quedaban vivas modoCopa/picadito/desafío de lo que se estuviera
  // jugando al momento de retomar.
  limpiarBanderasDeModo();
  modoAmistoso   = (s.tag === "amistoso");
  // Volver a prender la bandera específica del modo real guardado en el
  // snapshot (ver _partidaModoTag): si no se hace esto, Historia/Maratón/
  // Desafío del Día/Copa Rápida/Picadito retomaban la mano pero SIN su
  // bandera prendida, y quedaban huérfanos de sus propios hooks de fin de
  // modo.
  if (typeof window !== "undefined") {
    switch (s.tag) {
      case "historia":    window.modoHistoria      = true; break;
      case "maraton":     window.modoMaraton        = true; break;
      case "desafio_dia": window.modoDesafioDiario = true; break;
      case "copa_rapida": window.modoCopaRapida    = true; break;
      case "picadito":    window.modoPicadito      = true; break;
    }
  }

  S.puntosJugador = s.ptsJ || 0;
  S.puntosRival   = s.ptsR || 0;
  S.limitePuntos  = s.limite || 30;
  S.nombreJugador = s.nombre || S.nombreJugador;
  S.avatarJugador = s.avatar || S.avatarJugador;
  S.idRival       = (typeof s.idRival === "number") ? s.idRival : 0;
  S.juegoTerminado = false;

  if (s.eqJ) { const e = buscarEquipo(s.eqJ); if (e) { equipoSel = e.equipo; LIGA = e.liga; } }
  if (s.eqR) { const e = buscarEquipo(s.eqR); if (e) equipoRival = e.equipo; }

  // Pre-flip: repartirNuevaMano alterna el "mano" al arrancar, así que
  // dejamos el opuesto para que la mano repartida tenga el mano guardado.
  S.turnoMano = (s.turnoMano === "jugador") ? "rival" : "jugador";

  if (typeof irA === "function") irA("mesa");
  if (typeof _emitJuego === "function") _emitJuego("nuevoPartido");

  // Pintar escudos sin re-sortear el rival guardado
  _retomando = true;
  if (typeof aplicarEquipoEnMesa === "function") aplicarEquipoEnMesa();
  _retomando = false;

  if (typeof showToast === "function") showToast("🔄 Partida retomada");
  repartirNuevaMano();
}

/* Inyecta/actualiza el botón "Retomar partida" arriba del menú principal,
   solo si hay una partida 1J guardada con progreso. */
function montarBotonRetomar() {
  const nav = document.querySelector(".mm-nav");
  if (!nav) return;
  const s = partidaCargarSnapshot();
  let btn = document.getElementById("mm-btn-retomar");
  const hayProgreso = s && (s.ptsJ > 0 || s.ptsR > 0);

  if (!hayProgreso) { if (btn) btn.remove(); return; }

  const nomRival = (AVATARS[s.idRival] && AVATARS[s.idRival].name) || "Rival";
  // El snapshot guarda el modo real desde el 3 ago (_partidaModoTag), pero
  // esta etiqueta seguía en "amistoso o Modo DT": un Picadito guardado se
  // anunciaba como "Modo DT" (visto en prod, 8 ago).
  const ETIQUETA_MODO = {
    amistoso: "Amistoso", historia: "Historia", maraton: "Maratón",
    desafio_dia: "Desafío del Día", copa_rapida: "Copa Rápida",
    picadito: "Picadito", dt: "Modo DT",
  };
  const sub = `Vos ${s.ptsJ} – ${s.ptsR} ${nomRival} · ${ETIQUETA_MODO[s.tag] || "Modo DT"}`;
  if (!btn) {
    btn = document.createElement("button");
    btn.id = "mm-btn-retomar";
    btn.className = "mm-btn mm-btn-primary";
    btn.onclick = retomarPartida;
    nav.insertBefore(btn, nav.firstChild);
  }
  btn.innerHTML =
    '<span class="mm-btn-icon">🔄</span>' +
    '<span class="mm-btn-text"><strong>RETOMAR PARTIDA</strong><small>' + sub + '</small></span>';
}

/* Suscripciones al motor: guardar al repartir cada mano, borrar al terminar. */
if (typeof onJuego === "function") {
  onJuego("manoRepartida", partidaGuardarSnapshot);
  onJuego("finDePartido",  partidaBorrarSnapshot);
}

/* Mostrar/refrescar el botón al llegar al menú principal. */
window.addEventListener("load", () => { setTimeout(montarBotonRetomar, 400); });
if (typeof window.irA === "function") {
  const _irAprev = window.irA;
  window.irA = function (destino) {
    _irAprev.apply(this, arguments);
    if (destino === "main-menu") setTimeout(montarBotonRetomar, 30);
  };
}

/* Arranca el partido amistoso con los dos equipos elegidos por el jugador */
function iniciarPartidoAmistoso() {
  if (!amistosoEquipoJ || !amistosoEquipoR) {
    if (typeof showToast === "function") showToast("Elegí los dos equipos para el amistoso ⚽");
    return;
  }
  limpiarBanderasDeModo();
  modoAmistoso = true;
  equipoSel   = amistosoEquipoJ;
  equipoRival = amistosoEquipoR;
  const encJ = buscarEquipo(equipoSel.id);
  if (encJ) LIGA = encJ.liga;

  // _arrancarConNombreYAvatar(), NO setName(): setName() vuelve a limpiar
  // las banderas y apagaba el modoAmistoso que se acaba de prender arriba
  // (bug real, ver el comentario en juego_ui.js) — y de paso se perdían
  // los dos equipos elegidos a mano (aplicarEquipoEnMesa re-sortea sin
  // modoAmistoso prendido).
  if (typeof window._arrancarConNombreYAvatar === "function") window._arrancarConNombreYAvatar();
}

/* ── Hook: envolver setName() sin tocar juego_ui.js ── */
document.addEventListener("DOMContentLoaded", () => {
  renderSelectorEquipos();
  renderSelectorAmistoso();

  const guardado = localStorage.getItem(EQ_KEY);
  if (guardado) {
    const encontrado = buscarEquipo(guardado);
    if (encontrado) { equipoSel = encontrado.equipo; LIGA = encontrado.liga; }
  }

  // Se envuelve _arrancarConNombreYAvatar (no setName): setName() internamente
  // LLAMA a _arrancarConNombreYAvatar, así que envolver ahí alcanza para el
  // registro real de Modo DT — y de paso cubre a Copas/Mundial/Amistoso, que
  // desde hoy llaman a _arrancarConNombreYAvatar DIRECTO (no a setName(), que
  // les apagaba la bandera de su propio modo — ver el comentario en
  // juego_ui.js). Envolver solo setName() los hubiera dejado sin este pintado
  // de escudos.
  if (typeof window._arrancarConNombreYAvatar === "function") {
    const arrancarOriginal = window._arrancarConNombreYAvatar;
    window._arrancarConNombreYAvatar = function () {
      arrancarOriginal.apply(this, arguments);
      setTimeout(aplicarEquipoEnMesa, 50);
    };
  }
});


