//     mandan como mensajes al host, que las aplica con las funciones
//     "Rival" de este archivo (equivalentes a las del jugador, pero
//     para el bando "rival").
// ══════════════════════════════════════════════════════════════

// ── Serialización del estado ─────────────────────────────────────

const _ONLINE_CAMPOS_ESTADO = [
  "puntosJugador", "puntosRival", "limitePuntos",
  "manoJugador", "manoRival",
  "cartasRondaJugador", "cartasRondaRival", "ganadoresRonda",
  "rondaActual", "turnoActual", "turnoMano",
  "envidoCantado", "envidoTerminado", "nivelEnvido", "historialEnvido",
  "jugadorTiroEnR0", "rivalTiroEnR0",
  "trucoCantado", "nivelTruco", "nivelTrucoAceptado",
  "ultimoEnCantarTruco", "ultimoEnAceptarTruco",
  "cantoPendiente", "quienCantoPendiente",
  "trucoDiferido", "trucoDiferidoDe",
  // cfgFlor viaja porque es config de la PARTIDA y la fija el host: sin esto
  // el invitado se quedaba con su default local (false) y florPropiaPendiente()
  // le daba false teniendo flor → le aparecía el botón ENVIDO, lo apretaba y el
  // host se lo rechazaba en silencio. Botón muerto.
  "cfgFlor",
  "jugadorTieneFlor", "rivalTieneFlor", "florCantada", "florCantadaPor", "florTerminada",
  "jugadorPasoFlor", "rivalPasoFlor",
  "nivelFlor", "historialFlor",
  "revealEnvidoMano",
  "juegoTerminado",
];

// Espeja el reveal de envido/flor (las cartas que se muestran al fin de mano):
// swap jugador<->rival para la perspectiva del invitado.
function _espejarReveal(r) {
  if (!r) return null;
  return {
    titulo: r.titulo, apuesta: r.apuesta, ganoJugador: !r.ganoJugador,
    ptsJ: r.ptsR, ptsR: r.ptsJ, cartasJ: r.cartasR, cartasR: r.cartasJ,
  };
}

function netSerializarEstado() {
  const out = {};
  _ONLINE_CAMPOS_ESTADO.forEach(k => { out[k] = S[k]; });
  return out;
}

// 'jugador' <-> 'rival' ; deja 'parda', null, etc. sin tocar
function _swapRol(x) {
  if (x === "jugador") return "rival";
  if (x === "rival")   return "jugador";
  return x;
}

// Redacta una mano oculta: preserva la cuenta (para pintar los dorsos) pero
// NO manda las cartas reales. Evita que el invitado lea la mano del host por
// el WebSocket (la UI del rival solo cuenta cartas, nunca usa el valor).
function _redactarMano(mano) {
  return (mano || []).map(c => (c ? "?" : null));
}

// Invierte un snapshot para que el invitado lo vea desde su propio
// punto de vista ("jugador" = invitado, "rival" = host).
function netEspejarEstado(snap) {
  return {
    puntosJugador: snap.puntosRival,
    puntosRival:   snap.puntosJugador,
    limitePuntos:  snap.limitePuntos,

    manoJugador: snap.manoRival,                 // la mano del invitado (la ve él, ok)
    manoRival:   _redactarMano(snap.manoJugador), // la mano del HOST: redactada (no filtrar cartas)

    cartasRondaJugador: snap.cartasRondaRival,
    cartasRondaRival:   snap.cartasRondaJugador,
    ganadoresRonda:     (snap.ganadoresRonda || []).map(_swapRol),

    rondaActual: snap.rondaActual,
    turnoActual: _swapRol(snap.turnoActual),
    turnoMano:   _swapRol(snap.turnoMano),

    envidoCantado:   snap.envidoCantado,
    envidoTerminado: snap.envidoTerminado,
    nivelEnvido:     snap.nivelEnvido,
    historialEnvido: snap.historialEnvido,
    jugadorTiroEnR0: snap.rivalTiroEnR0,
    rivalTiroEnR0:   snap.jugadorTiroEnR0,

    trucoCantado:         snap.trucoCantado,
    nivelTruco:           snap.nivelTruco,
    nivelTrucoAceptado:   snap.nivelTrucoAceptado,
    ultimoEnCantarTruco:  _swapRol(snap.ultimoEnCantarTruco),
    ultimoEnAceptarTruco: _swapRol(snap.ultimoEnAceptarTruco),

    cantoPendiente:      snap.cantoPendiente,
    quienCantoPendiente: _swapRol(snap.quienCantoPendiente),

    trucoDiferido:   snap.trucoDiferido,
    trucoDiferidoDe: _swapRol(snap.trucoDiferidoDe),

    // La flor del HOST es información privada hasta que la canta — igual que
    // sus cartas. Se redacta: si se mandaba tal cual, el invitado sabía que
    // el host tenía flor antes del canto (y florTerminada se deduce de lo
    // mismo, así que también se recalcula desde lo que el invitado sí puede
    // saber: su propia flor).
    cfgFlor:          snap.cfgFlor,          // la regla la fija el host
    jugadorTieneFlor: snap.rivalTieneFlor,   // la del invitado: es suya, la ve
    rivalTieneFlor:   snap.florCantada ? snap.jugadorTieneFlor : false,
    florCantada:      snap.florCantada,
    florCantadaPor:   _swapRol(snap.florCantadaPor),
    florTerminada:    snap.florCantada
                        ? snap.florTerminada
                        : (!snap.cfgFlor || !snap.rivalTieneFlor),
    jugadorPasoFlor:  snap.rivalPasoFlor,
    rivalPasoFlor:    snap.florCantada ? snap.jugadorPasoFlor : false,
    nivelFlor:        snap.nivelFlor,
    historialFlor:    snap.historialFlor,

    revealEnvidoMano: _espejarReveal(snap.revealEnvidoMano),

    juegoTerminado: snap.juegoTerminado,
  };
}

// ── Aplicar estado recibido (lado invitado) ──────────────────────

// El ENVÍO ya usaba la allowlist _ONLINE_CAMPOS_ESTADO; la RECEPCIÓN copiaba
// cualquier clave que mandara el host. Con `esHost:true` el guest se creía
// autoritativo y dejaba de mandar sus jugadas (mesa muda), y con `idRival`
// fuera de rango AVATARS[...] tiraba TypeError en cada fin de mano.
// Misma lista en las dos direcciones: la clase entera se cierra acá.
function _estadoSeguro(estado) {
  const out = {};
  if (!estado || typeof estado !== "object") return out;
  _ONLINE_CAMPOS_ESTADO.forEach(k => { if (k in estado) out[k] = estado[k]; });
  return out;
}

function netAplicarEstadoRemoto(estadoCrudo) {
  const estado = _estadoSeguro(estadoCrudo);
  const prev = {
    cantoPendiente:      S.cantoPendiente,
    quienCantoPendiente: S.quienCantoPendiente,
    envidoTerminado:     S.envidoTerminado,
    trucoCantado:        S.trucoCantado,
    nivelTruco:          S.nivelTruco,
    rondaActual:         S.rondaActual,
    puntosJugador:       S.puntosJugador,
    puntosRival:         S.puntosRival,
    juegoTerminado:      S.juegoTerminado,
    ganadoresRondaLen:   (S.ganadoresRonda || []).length,
    historialEnvido:     S.historialEnvido || [],
    florTerminada:       S.florTerminada,
    florCantada:         S.florCantada,
  };

  // El reveal de envido es transitorio: el host lo pone al resolver el envido
  // y lo limpia al fin de mano. Para que no se pierda por una carrera de
  // renders, NO lo pisamos con null — solo lo seteamos cuando llega con datos;
  // el propio overlay de resultado del invitado lo consume y limpia.
  const reveal = estado.revealEnvidoMano;
  delete estado.revealEnvidoMano;

  Object.assign(S, estado);
  if (reveal) S.revealEnvidoMano = reveal;

  _onlineNotificarCambios(prev, estado);

  if (typeof actualizarTodaLaInterfaz === "function") actualizarTodaLaInterfaz();
  if (typeof evaluarTurnoActual === "function") evaluarTurnoActual();
}

// Toasts/sonidos al recibir un nuevo estado, para que el invitado
// se entere de lo que pasó (cantos del rival, resultado de envidos,
// rondas, manos y fin de partido) sin tener que mirar la mesa fijo.
function _onlineNotificarCambios(prev, nuevo) {
  const nombreRival = (typeof AVATARS !== "undefined" && AVATARS[S.idRival])
    ? AVATARS[S.idRival].name : "Rival";

  // ── Nuevo canto del rival ──────────────────────────────────
  if (nuevo.cantoPendiente && !prev.cantoPendiente && nuevo.quienCantoPendiente === "rival") {
    if (nuevo.cantoPendiente === "envido") {
      const labels = { envido: "¡ENVIDO!", real: "¡REAL ENVIDO!", falta: "¡FALTA ENVIDO!" };
      const hist = nuevo.historialEnvido || [];
      const tipo = hist[hist.length - 1] || "envido";
      const label = labels[tipo] || "¡ENVIDO!";
      showToast(`${nombreRival}: ${label}`);
      if (typeof mostrarOverlayCanto === "function") mostrarOverlayCanto(label, "rival");
      if (typeof playSound === "function") playSound("canto");
    } else if (nuevo.cantoPendiente === "truco") {
      const labels = { 2: "¡TRUCO!", 3: "¡RETRUCO!", 4: "¡VALE 4!" };
      const label = labels[nuevo.nivelTruco] || "¡TRUCO!";
      showToast(`${nombreRival}: ${label}`);
      if (typeof mostrarOverlayCanto === "function") mostrarOverlayCanto(label, "rival");
      if (typeof playSound === "function") playSound("silbato");
    } else if (nuevo.cantoPendiente === "flor") {
      const labels = { flor: "¡FLOR!", contraflor: "¡CONTRAFLOR!", contraflorresto: "¡CONTRAFLOR AL RESTO!" };
      const hist = nuevo.historialFlor || [];
      const tipo = hist[hist.length - 1] || "flor";
      const label = labels[tipo] || "¡FLOR!";
      showToast(`${nombreRival}: ${label}`);
      if (typeof mostrarOverlayCanto === "function") mostrarOverlayCanto(label, "rival");
      if (typeof playSound === "function") playSound("canto");
    }
  }

  // ── Flor recién cantada ──────────────────────────────────────
  // Antes esto asumía que la había cantado el rival SIEMPRE, así que el
  // invitado que cantaba su propia flor recibía "HOST: ¡FLOR!". Ahora el
  // estado dice quién la cantó (florCantadaPor, ya espejado).
  if (nuevo.florCantada && !prev.florCantada && !nuevo.cantoPendiente) {
    const laCantoElRival = nuevo.florCantadaPor !== "jugador";
    showToast(laCantoElRival ? `${nombreRival}: ¡FLOR!` : `Cantaste: ¡FLOR!`);
    if (typeof mostrarOverlayCanto === "function") {
      mostrarOverlayCanto("¡FLOR!", laCantoElRival ? "rival" : "jugador");
    }
    if (typeof playSound === "function") playSound("canto");
  }

  // ── Envido resuelto ─────────────────────────────────────────
  // Si la FLOR acaba de anular el envido, el envido "termina" sin pagar nada y
  // los puntos que se movieron son los de la flor. Sin esta guarda el invitado
  // veía "ganó el envido (+3)" Y "ganó la flor (+3)" por los mismos 3 puntos:
  // uno era mentira y el otro sonaba a que había perdido 6.
  const florAnuloElEnvido = nuevo.florCantada && !prev.florCantada;
  if (prev.cantoPendiente === "envido" && !nuevo.cantoPendiente
      && nuevo.envidoTerminado && !prev.envidoTerminado && !florAnuloElEnvido) {
    if (nuevo.puntosJugador > prev.puntosJugador) {
      showToast(`✅ Ganaste el envido (+${nuevo.puntosJugador - prev.puntosJugador})`);
      if (typeof playSound === "function") playSound("punto");
    } else if (nuevo.puntosRival > prev.puntosRival) {
      showToast(`❌ ${nombreRival} ganó el envido (+${nuevo.puntosRival - prev.puntosRival})`);
      if (typeof playSound === "function") playSound("parda");
    }
  }

  // ── Flor resuelta (con o sin respuesta) ──────────────────────
  // Ojo: florTerminada llega REDACTADA mientras nadie cantó flor (para no
  // filtrarle al invitado la flor del host), así que para el invitado sin
  // flor nunca hay transición false→true. El disparo bueno en ese caso es
  // el de florCantada; las dos ramas piden que los puntos se hayan movido,
  // así que no se duplica el aviso.
  if ((nuevo.florTerminada && !prev.florTerminada) ||
      (nuevo.florCantada   && !prev.florCantada)) {
    if (nuevo.puntosJugador > prev.puntosJugador) {
      showToast(`✅ Ganaste la flor (+${nuevo.puntosJugador - prev.puntosJugador})`);
      if (typeof playSound === "function") playSound("punto");
    } else if (nuevo.puntosRival > prev.puntosRival) {
      showToast(`❌ ${nombreRival} ganó la flor (+${nuevo.puntosRival - prev.puntosRival})`);
      if (typeof playSound === "function") playSound("parda");
    }
  }

  // ── Truco aceptado ────────────────────────────────────────────
  if (prev.cantoPendiente === "truco" && !nuevo.cantoPendiente
      && nuevo.trucoCantado && !prev.trucoCantado) {
    showToast(`${nombreRival}: ¡QUIERO!`);
    if (typeof mostrarOverlayCanto === "function") mostrarOverlayCanto("¡QUIERO!", "rival");
  }

  // ── Ronda resuelta ────────────────────────────────────────────
  const ganadoresLen = (nuevo.ganadoresRonda || []).length;
  if (ganadoresLen > prev.ganadoresRondaLen) {
    const g = nuevo.ganadoresRonda[ganadoresLen - 1];
    if (g === "jugador")     showToast("¡Ganaste la ronda!");
    else if (g === "rival")  showToast(`${nombreRival} ganó la ronda.`);
    else                      showToast("Ronda parda.");
  }

  // ── Fin de mano (se repartieron cartas nuevas) ────────────────
  if (!nuevo.juegoTerminado && nuevo.rondaActual === 0 && ganadoresLen === 0
      && (prev.ganadoresRondaLen > 0 || prev.rondaActual > 0)) {
    if (nuevo.puntosJugador > prev.puntosJugador) {
      const pts = nuevo.puntosJugador - prev.puntosJugador;
      showToast(`¡Ganaste la mano! +${pts}`);
      if (typeof mostrarOverlayResultadoMano === "function") mostrarOverlayResultadoMano("gano", pts);
    } else if (nuevo.puntosRival > prev.puntosRival) {
      const pts = nuevo.puntosRival - prev.puntosRival;
      showToast(`${nombreRival} ganó la mano.`);
      if (typeof mostrarOverlayResultadoMano === "function") mostrarOverlayResultadoMano("pierde", pts);
    }
    if (typeof playSound === "function") playSound("deal");
  }

  // ── Fin del partido ────────────────────────────────────────────
  if (nuevo.juegoTerminado && !prev.juegoTerminado) {
    if (nuevo.puntosJugador > nuevo.puntosRival) {
      showToast("🏆 ¡FELICITACIONES! GANASTE EL PARTIDO 🏆");
      if (typeof playSound === "function") playSound("win");
    } else {
      showToast(`${nombreRival} ganó el partido. ¡Otra vez será!`);
      if (typeof playSound === "function") playSound("lose");
    }
    // El guest nunca corre juego.js (no dispara 'finDePartido'): se
    // reporta acá, sobre el mismo estado espejado que ya aplicó.
    if (typeof reportarResultadoOnline === "function") {
      reportarResultadoOnline(nuevo.puntosJugador, nuevo.puntosRival, nuevo.limitePuntos);
    }
    // Y por lo mismo, se emite el evento a mano para que la pantalla de fin
    // de partido (overlay con REVANCHA/CONTINUAR) también salga del lado guest.
    if (typeof _emitJuego === "function") {
      _emitJuego("finDePartido", {
        puntosJugador: nuevo.puntosJugador,
        puntosRival:   nuevo.puntosRival,
        limite:        nuevo.limitePuntos || S.limitePuntos,
      });
    }
  }
}

// ── Arranque de la partida online ────────────────────────────────

// El HOST recibe el "hola" del invitado → arranca el motor real.
function onlineIniciarPartidaHost() {
  ONLINE.partidaIniciada = true;
  ONLINE._avatarsBaseLen = AVATARS.length;
  AVATARS.push({ name: ONLINE.nombreRival || "Rival", icon: ONLINE.avatarRival || "avatares/hincha_misterioso.png" });
  S.idRival = AVATARS.length - 1;

  S.nombreJugador = ONLINE.nombre || "Vos";
  S.avatarJugador = "🤠";
  S.modoOnline    = true;
  S.esHost        = true;
  S.puntosJugador = 0;
  S.puntosRival   = 0;
  // Sorteamos quién es mano para que no sea siempre el mismo.
  S.turnoMano     = Math.random() < 0.5 ? "jugador" : "rival";
  S.juegoTerminado = false;

  if (typeof _iniciarPartida === "function") _iniciarPartida();

  // _iniciarPartida() llama a seleccionarRivalAleatorio(), que pisa
  // S.idRival con un avatar al azar: lo volvemos a fijar al del
  // rival real (ya conectado online).
  S.idRival = AVATARS.length - 1;
}

// El INVITADO recibe el primer "estado" del host → se inicializa.
function onlineIniciarPartidaGuest(payload) {
  ONLINE.partidaIniciada = true;
  ONLINE._avatarsBaseLen = AVATARS.length;
  // El host también es un cliente cualquiera: su nombre y su avatar se
  // sanean igual que los del invitado.
  AVATARS.push({ name: nombreSeguro(payload.nombreRival, "Rival"), icon: avatarSeguro(payload.avatarRival) });
  S.idRival = AVATARS.length - 1;

  S.nombreJugador = ONLINE.nombre || "Vos";
  S.avatarJugador = "🤠";
  S.modoOnline    = true;
  S.esHost        = false;
  S.juegoTerminado = false;

  if (typeof irA === "function") irA("mesa");
}

// ── Funciones "Rival" (host aplicando acciones del invitado) ─────
// Son el espejo de las funciones *Jugador / *Subida de juego.js,
// pero para el bando "rival" (controlado por el invitado humano).

function cantarFlorRival() {
  if (S.cantoPendiente) return;
  if (S.turnoActual !== "rival") return;
  if (S.florCantada) return;
  if (typeof florSigueVivo !== "function" || !florSigueVivo()) return;
  if (!S.rivalTieneFlor) return;

  playSound("canto");
  _registrarCantoFlor('flor');
  S.florCantada = true;
  S.florCantadaPor = "rival";

  showToast(`${AVATARS[S.idRival].name}: ¡FLOR!`);
  if (typeof mostrarOverlayCanto === "function") mostrarOverlayCanto("¡FLOR!", "rival");

  if (!S.jugadorTieneFlor) {
    _resolverFlorSinContrincante("rival");
    return;
  }

  S.cantoPendiente      = "flor";
  S.quienCantoPendiente = "rival";
  actualizarTodaLaInterfaz();
  evaluarTurnoActual();
}

// "Achicar" del invitado (rival): se guarda la flor sin cantarla.
// Espejo de pasarFlorJugador() para el bando "rival".
function pasarFlorRival() {
  if (S.cantoPendiente) return;
  if (S.turnoActual !== "rival") return;
  if (S.florCantada) return;
  if (S.rivalPasoFlor) return;
  if (typeof florSigueVivo !== "function" || !florSigueVivo()) return;
  if (!S.rivalTieneFlor) return;

  playSound("click");
  S.rivalPasoFlor = true;
  showToast(`${AVATARS[S.idRival].name} se guardó la flor.`);

  if (!S.jugadorTieneFlor) {
    S.florTerminada = true;
  }

  actualizarTodaLaInterfaz();
  evaluarTurnoActual();
}

// Responde a una Flor cantada por el host (jugador) que está esperando
// respuesta. Espejo de responderFlorJugador() para el bando "rival".
function responderFlorRival(tipo) {
  if (!S.cantoPendiente || S.cantoPendiente !== "flor") return;
  if (S.quienCantoPendiente !== "jugador") return;
  // Igual que del lado del jugador: a una flor pelada no se le dice "no quiero".
  if (tipo === 'no-quiero' && !S.historialFlor.includes('contraflor')
      && !S.historialFlor.includes('contraflorresto')) return;

  if (tipo === 'quiero' || tipo === 'no-quiero') {
    playSound("click");
    if (tipo === 'quiero') {
      showToast(`${AVATARS[S.idRival].name}: ¡CON FLOR QUIERO!`);
      if (typeof mostrarOverlayCanto === "function") mostrarOverlayCanto("¡CON FLOR QUIERO!", "rival");
      setTimeout(() => resolverFlorMesa("quiero"), 400);
    } else {
      showToast(`${AVATARS[S.idRival].name}: NO QUIERO.`);
      if (typeof mostrarOverlayCanto === "function") mostrarOverlayCanto("NO QUIERO", "rival");
      setTimeout(() => resolverFlorMesa("no-quiero"), 400);
    }
    return;
  }

  // contraflor / contraflorresto: sube la apuesta y pasa la pelota al host.
  // Misma validación que el envido: el `tipo` llega por red, se chequea
  // contra la regla compartida antes de mover el pozo.
  if (typeof reglasFlorRaises === "function" &&
      !reglasFlorRaises(S.historialFlor || []).includes(tipo)) return;
  playSound("canto");
  _registrarCantoFlor(tipo);
  S.quienCantoPendiente = "rival"; // ahora el host (jugador) tiene que responder

  const labels = { contraflor: "¡CONTRAFLOR!", contraflorresto: "¡CONTRAFLOR AL RESTO!" };
  showToast(`${AVATARS[S.idRival].name}: ${labels[tipo]}`);
  if (typeof mostrarOverlayCanto === "function") mostrarOverlayCanto(labels[tipo], "rival");
  actualizarTodaLaInterfaz();
  evaluarTurnoActual();
}

function cantarEnvidoRival(tipo) {
  if (S.cantoPendiente) return;
  if (S.turnoActual !== "rival") return;
  if (!envidoSigueVivo()) return;
  // Con flor propia sin resolver no se canta envido (se canta la flor o se achica)
  if (typeof florPropiaPendiente === "function" && florPropiaPendiente("rival")) return;
  if (S.envidoCantado && (tipo === 'real' || tipo === 'falta')) return;

  playSound("canto");
  _registrarCantoEnvido(tipo);
  S.envidoCantado       = true;
  S.cantoPendiente      = "envido";
  S.quienCantoPendiente = "rival";

  const labels = { envido: "¡ENVIDO!", real: "¡REAL ENVIDO!", falta: "¡FALTA ENVIDO!" };
  showToast(`${AVATARS[S.idRival].name}: ${labels[tipo]}`);
  if (typeof mostrarOverlayCanto === "function") mostrarOverlayCanto(labels[tipo], "rival");
  actualizarTodaLaInterfaz();
  evaluarTurnoActual();
}

function cantarTrucoRival(nivel) {
  if (S.cantoPendiente) return;
  if (S.juegoTerminado) return;
  // El truco se canta en tu turno. Sin esta guarda el host aceptaba el
  // "cantarTruco" del invitado en cualquier momento de la mano.
  if (S.turnoActual !== "rival") return;
  if (typeof _nivelTrucoDisponible !== "function") return;
  if (_nivelTrucoDisponible("rival") !== nivel) return;

  playSound("silbato");
  S.cantoPendiente       = "truco";
  S.quienCantoPendiente  = "rival";
  S.ultimoEnCantarTruco  = "rival";
  S.nivelTruco           = nivel;
  if (nivel > 2) S.trucoCantado = true;

  const labels = { 2: "¡TRUCO!", 3: "¡RETRUCO!", 4: "¡VALE 4!" };
  showToast(`${AVATARS[S.idRival].name}: ${labels[nivel]}`);
  if (typeof mostrarOverlayCanto === "function") mostrarOverlayCanto(labels[nivel], "rival");
  actualizarTodaLaInterfaz();
  evaluarTurnoActual();
}

function responderCantoRival(acepta) {
  if (!S.cantoPendiente || S.quienCantoPendiente !== "jugador") return;
  playSound("click");

  if (S.cantoPendiente === "envido") {
    // Mismo criterio que responderCantoJugador (juego.js): responder el
    // envido sin declarar una flor propia pendiente equivale a guardársela
    // ("achicar") — si no, el invitado podía ganar el envido con QUIERO y
    // DESPUÉS seguir teniendo el botón FLOR disponible, cobrando las dos.
    if (typeof florPropiaPendiente === "function" && florPropiaPendiente("rival")) {
      S.rivalPasoFlor = true;
      if (!S.jugadorTieneFlor) S.florTerminada = true;
    }
    if (acepta) {
      showToast(`${AVATARS[S.idRival].name}: ¡QUIERO!`);
      if (typeof mostrarOverlayCanto === "function") mostrarOverlayCanto("¡QUIERO!", "rival");
      setTimeout(() => resolverEnvidoMesa("quiero"), 400);
    } else {
      showToast(`${AVATARS[S.idRival].name}: NO QUIERO.`);
      if (typeof mostrarOverlayCanto === "function") mostrarOverlayCanto("NO QUIERO", "rival");
      setTimeout(() => resolverEnvidoMesa("no-quiero"), 400);
    }
  } else if (S.cantoPendiente === "truco") {
    if (acepta) {
      showToast(`${AVATARS[S.idRival].name}: ¡QUIERO!`);
      if (typeof mostrarOverlayCanto === "function") mostrarOverlayCanto("¡QUIERO!", "rival");
      S.trucoCantado          = true;
      S.nivelTrucoAceptado    = S.nivelTruco;
      S.ultimoEnAceptarTruco  = "rival";
      S.cantoPendiente        = null;
      S.quienCantoPendiente   = null;
      actualizarTodaLaInterfaz();
      evaluarTurnoActual();
    } else {
      showToast(`${AVATARS[S.idRival].name} se fue al mazo.`);
      if (typeof mostrarOverlayCanto === "function") mostrarOverlayCanto("AL MAZO", "rival");
      irseAlMazo("rival");
    }
  }
}

function responderEnvidoConSubidaRival(tipo) {
  if (!S.cantoPendiente || S.cantoPendiente !== "envido") return;
  if (S.quienCantoPendiente !== "jugador") return;
  // La suba llega por RED: validar la legalidad ACÁ, en el host, contra la
  // misma regla compartida que usa el 2v2 (reglas_truco.js). La UI solo
  // ofrece botones legales, pero un guest modificado mandaba "envido" sobre
  // un doble envido, o "real" después de un real, y el pozo escalaba de más.
  if (typeof reglasEnvidoRaises === "function" &&
      !reglasEnvidoRaises(S.historialEnvido || []).includes(tipo)) return;
  // Con flor propia sin resolver el invitado no sube el envido: responde con
  // flor (acción "envido_con_flor").
  if (typeof florPropiaPendiente === "function" && florPropiaPendiente("rival")) return;

  playSound("canto");
  _registrarCantoEnvido(tipo);
  S.envidoCantado       = true;
  S.cantoPendiente      = "envido";
  S.quienCantoPendiente = "rival"; // ahora el host tiene que responder

  const labels = { envido: "¡ENVIDO!", real: "¡REAL ENVIDO!", falta: "¡FALTA ENVIDO!" };
  showToast(`${AVATARS[S.idRival].name}: ${labels[tipo]}`);
  if (typeof mostrarOverlayCanto === "function") mostrarOverlayCanto(labels[tipo], "rival");
  actualizarTodaLaInterfaz();
  evaluarTurnoActual();
}

function responderTrucoSubidaRival(nivel) {
  if (S.cantoPendiente !== "truco" || S.quienCantoPendiente !== "jugador") return;
  if (nivel !== S.nivelTruco + 1 || nivel > 4) return;

  playSound("silbato");

  // Aceptación implícita del nivel cantado por el host
  S.trucoCantado         = true;
  S.nivelTrucoAceptado   = S.nivelTruco;
  S.ultimoEnAceptarTruco = "rival";

  // El invitado canta el nivel superior — el host debe responder
  S.cantoPendiente       = "truco";
  S.quienCantoPendiente  = "rival";
  S.ultimoEnCantarTruco  = "rival";
  S.nivelTruco           = nivel;

  const labels = { 3: "¡RETRUCO!", 4: "¡VALE 4!" };
  showToast(`${AVATARS[S.idRival].name}: ${labels[nivel]}`);
  if (typeof mostrarOverlayCanto === "function") mostrarOverlayCanto(labels[nivel], "rival");
  actualizarTodaLaInterfaz();
  evaluarTurnoActual();
}

function irseAlMazoConCantoPendienteRival() {
  if (!S.cantoPendiente || S.quienCantoPendiente !== "jugador") return;
  playSound("click");

  if (S.cantoPendiente === "flor") {
    S.florTerminada       = true;
    const pts             = puntosFlorNoQuiero();
    S.puntosJugador      += pts;
    S.cantoPendiente      = null;
    S.quienCantoPendiente = null;
    S.trucoDiferido       = false;
    S.trucoDiferidoDe     = null;

    showToast(`${AVATARS[S.idRival].name} no quiso la flor. Vos +${pts} pto${pts > 1 ? "s" : ""}.`);
    if (typeof mostrarOverlayCanto === "function") mostrarOverlayCanto("AL MAZO", "rival");
    actualizarTodaLaInterfaz();
    guardarProgreso();

    if (S.puntosJugador >= S.limitePuntos) {
      setTimeout(repartirNuevaMano, 1000);
      return;
    }
    setTimeout(() => irseAlMazo("rival"), 600);

  } else if (S.cantoPendiente === "envido") {
    S.envidoTerminado     = true;
    const pts             = puntosEnvidoNoQuiero();
    S.puntosJugador      += pts;
    S.cantoPendiente      = null;
    S.quienCantoPendiente = null;
    S.trucoDiferido       = false;
    S.trucoDiferidoDe     = null;

    showToast(`${AVATARS[S.idRival].name} no quiso el envido. Vos +${pts} pto${pts > 1 ? "s" : ""}.`);
    if (typeof mostrarOverlayCanto === "function") mostrarOverlayCanto("AL MAZO", "rival");
    actualizarTodaLaInterfaz();
    guardarProgreso();

    if (S.puntosJugador >= S.limitePuntos) {
      setTimeout(repartirNuevaMano, 1000);
      return;
    }
    setTimeout(() => irseAlMazo("rival"), 600);

  } else if (S.cantoPendiente === "truco") {
    S.cantoPendiente      = null;
    S.quienCantoPendiente = null;
    showToast(`${AVATARS[S.idRival].name} se fue al mazo.`);
    if (typeof mostrarOverlayCanto === "function") mostrarOverlayCanto("AL MAZO", "rival");
    irseAlMazo("rival");
  }
}

function irseAlMazoRival() {
  if (S.cantoPendiente) return;
  if (S.juegoTerminado) return;
  irseAlMazo("rival");
}

// ── Dispatcher de mensajes de red ────────────────────────────────

function onlineProcesarMensaje(payload) {
  if (!payload || typeof payload !== "object" || !payload.accion) return;

  switch (payload.accion) {
    case "hola":
      // Nombre y avatar los elige el cliente de enfrente: se sanean ACÁ, en
      // el borde, para que nada aguas abajo tenga que acordarse de hacerlo.
      ONLINE.nombreRival = nombreSeguro(payload.nombre, "Rival");
      ONLINE.avatarRival = avatarSeguro(payload.avatar);
      // El nivel de estadio del rival decide, junto con el propio, qué mesa
      // ven los dos (el del más avanzado). Viene de la red: se satura al
      // rango real de la escalera acá, en el borde, o un cliente modificado
      // podría mandar cualquier cosa y romper la resolución del escenario.
      ONLINE.nivelRival = Math.max(1, Math.min(6, parseInt(payload.nivel, 10) || 1));
      if (typeof window.escenarioSincronizar === "function") window.escenarioSincronizar();
      if (NET.rol === "host") {
        if (!ONLINE.partidaIniciada) {
          onlineIniciarPartidaHost();
        } else if (S.modoOnline && typeof actualizarTodaLaInterfaz === "function") {
          // El invitado se reconectó a una partida en curso: resincronizamos
          // su nombre/avatar en AVATARS (por si el "hola" trae datos nuevos o
          // se habían perdido) y le reenviamos el estado actual.
          if (typeof AVATARS !== "undefined" && AVATARS[S.idRival]) {
            AVATARS[S.idRival].name = ONLINE.nombreRival || AVATARS[S.idRival].name;
            AVATARS[S.idRival].icon = ONLINE.avatarRival || AVATARS[S.idRival].icon;
          }
          if (typeof showToast === "function") showToast("✅ Tu rival se reconectó.");
          actualizarTodaLaInterfaz();
          // Reenvío EXPLÍCITO del estado: no confiamos en que el 'render'
          // de actualizarTodaLaInterfaz dispare el envío (puede no haber
          // cambios que renderizar, o llegar antes de que el guest esté
          // listo). Sin esto, el guest reconectado se queda con la mesa
          // vacía. Es idempotente: si el render también manda, el guest
          // recibe el mismo estado dos veces y no pasa nada.
          if (typeof netEnviar === "function") {
            netEnviar({
              accion: "estado",
              estado: netEspejarEstado(netSerializarEstado()),
              nombreRival: S.nombreJugador,
              avatarRival: S.avatarJugador,
            });
          }
        }
      }
      break;

    case "estado":
      if (NET.rol !== "guest") return; // solo el invitado recibe estado
      if (!S.modoOnline) onlineIniciarPartidaGuest(payload);
      netAplicarEstadoRemoto(payload.estado);
      break;

    // ── Acciones del invitado (solo el host las procesa) ────────
    case "jugarCarta":
    case "cantarEnvido":
    case "cantarTruco":
    case "responderCanto":
    case "subirEnvido":
    case "subirTruco":
    case "truco_con_envido":
    case "envido_con_flor":
    case "cantarFlor":
    case "pasarFlor":
    case "responderFlor":
    case "truco_con_flor":
    case "mazoConCanto":
    case "mazo":
      _dispatchAccionRival(payload);
      break;

    default:
      break;
  }
}

function _dispatchAccionRival(payload) {
  if (NET.rol !== "host" || !S.modoOnline || !S.esHost) return;

  switch (payload.accion) {
    case "jugarCarta": {
      const idx = Number(payload.idx);
      if (!Number.isInteger(idx) || idx < 0 || idx > 2) break;
      if (S.turnoActual === "rival" && !S.cantoPendiente && !S.juegoTerminado
          && S.manoRival[idx]) {
        jugarCartaRivalFisico(idx);
      }
      break;
    }
    case "cantarEnvido":
      cantarEnvidoRival(payload.tipo);
      break;
    case "cantarTruco":
      cantarTrucoRival(payload.nivel);
      break;
    case "responderCanto":
      responderCantoRival(!!payload.acepta);
      break;
    case "subirEnvido":
      responderEnvidoConSubidaRival(payload.tipo);
      break;
    case "subirTruco":
      responderTrucoSubidaRival(payload.nivel);
      break;
    case "truco_con_envido":
      if (typeof responderTrucoConEnvido === "function") {
        responderTrucoConEnvido("rival", payload.tipo);
      }
      break;
    case "envido_con_flor":
      if (typeof responderEnvidoConFlor === "function") {
        responderEnvidoConFlor("rival");
      }
      break;
    case "cantarFlor":
      cantarFlorRival();
      break;
    case "pasarFlor":
      pasarFlorRival();
      break;
    case "responderFlor":
      responderFlorRival(payload.tipo);
      break;
    case "truco_con_flor":
      if (typeof responderTrucoConFlor === "function") {
        responderTrucoConFlor("rival");
      }
      break;
    case "mazoConCanto":
      irseAlMazoConCantoPendienteRival();
      break;
    case "mazo":
      irseAlMazoRival();
      break;
  }
}

// ── Enganches al motor existente ─────────────────────────────────

let _ultimoEstadoEnviado = null;

function _netBroadcastEstado() {
  if (!S.modoOnline || !S.esHost || typeof netEnviar !== "function") return;
  const estado = netEspejarEstado(netSerializarEstado());
  const firma = JSON.stringify(estado);
  if (firma === _ultimoEstadoEnviado) return;
  _ultimoEstadoEnviado = firma;
  netEnviar({
    accion: "estado",
    estado,
    nombreRival: S.nombreJugador,
    avatarRival: S.avatarJugador,
  });
}

// Cada vez que se redibuja toda la interfaz, si somos el host de
// una partida online, mandamos el estado espejado al invitado.
// (Antes esto wrappeaba actualizarTodaLaInterfaz; ahora nos suscribimos
// al evento 'render' emitido desde juego_ui.js vía onJuego/_emitJuego.)
if (typeof onJuego === "function") {
  onJuego("render", _netBroadcastEstado);
}

// evaluarTurnoActual() ajusta S.turnoActual (y corre después de S.rondaActual++)
// mediante re-renders PARCIALES: nunca llama a actualizarTodaLaInterfaz(), así
// que no emite 'render' y el invitado se quedaba con el turno/ronda viejos —
// veía "TU TURNO" cuando no le tocaba y el host le descartaba cada click.
if (typeof evaluarTurnoActual === "function") {
  const _evaluarTurnoActualBase = evaluarTurnoActual;
  evaluarTurnoActual = function () {
    const r = _evaluarTurnoActualBase.apply(this, arguments);
    _netBroadcastEstado();
    return r;
  };
}

// El gateo de turnoRival() en modo online ahora vive directo en
// ia.js (turnoRival hace `if (S.modoOnline) return;`), ya no hace
// falta wrappearla acá.

// ── Watchdog: forfeit automático si el invitado queda AFK ─────────
// El host es quien corre el motor: si le toca jugar o responder al
// invitado y no lo hace en TURNO_TIMEOUT_MS (socket abierto pero nadie
// del otro lado — pestaña en background, se fue, lo que sea), el host
// resuelve por él con la opción más simple, para no trabar la partida
// indefinidamente. No aplica a las propias decisiones del host (esas
// las toma la persona que tiene el control acá).
const TURNO_TIMEOUT_MS = 45000;
let _watchdogTimer = null;

// true si, del lado del host, se está esperando una acción DEL INVITADO
// (jugar carta o responder un canto que cantó el host).
function _esperandoAlInvitado() {
  if (S.juegoTerminado) return false;
  if (S.cantoPendiente) return S.quienCantoPendiente === "jugador";
  return S.turnoActual === "rival";
}

function _forzarAccionInvitado() {
  if (!S.modoOnline || !S.esHost || S.juegoTerminado) return;
  if (S.cantoPendiente) {
    if (S.cantoPendiente === "flor") {
      // A una flor PELADA no se le dice "no quiero" (es ilegal y
      // responderFlorRival lo rechaza sin cambiar nada, lo que dejaba el
      // watchdog muerto y la mesa colgada). Lo unico legal ahi es comparar.
      const hayContra = S.historialFlor &&
        (S.historialFlor.includes("contraflor") || S.historialFlor.includes("contraflorresto"));
      responderFlorRival(hayContra ? "no-quiero" : "quiero");
      return;
    }
    responderCantoRival(false); // envido/truco: no quiero
    return;
  }
  if (S.turnoActual === "rival") {
    // Jugamos la carta MÁS FLOJA del rival, no la primera del array —
    // antes usaba findIndex(c => c), que podía tirarle el ancho de
    // espadas sin querer. Mismo criterio de fuerza que ia.js (C[c].f).
    const mano = S.manoRival || [];
    let idx = -1, minFuerza = Infinity;
    mano.forEach((c, i) => {
      if (!c) return;
      const f = C[c] ? C[c].f : 0;
      if (f < minFuerza) { minFuerza = f; idx = i; }
    });
    if (idx >= 0) jugarCartaRivalFisico(idx);
  }
}

function _watchdogTick() {
  _watchdogTimer = null;
  if (!S.modoOnline || !S.esHost || !_esperandoAlInvitado()) return;
  if (typeof showToast === "function") showToast("⏱️ Tu rival tardó demasiado — se resuelve solo.");
  _forzarAccionInvitado();
}

if (typeof onJuego === "function") {
  onJuego("render", () => {
    if (!S.modoOnline || !S.esHost) return;
    if (_watchdogTimer) { clearTimeout(_watchdogTimer); _watchdogTimer = null; }
    if (_esperandoAlInvitado()) _watchdogTimer = setTimeout(_watchdogTick, TURNO_TIMEOUT_MS);
  });
}


;/* ── reporte_resultado.js ── */
// ══════════════════════════════════════════════════════════════
// REPORTE DE RESULTADO — cada cliente manda su propio reporte del
// resultado final al servidor (confirmación doble: ver plan del bot
// de torneos, server/resultado.js). El HOST se engancha acá al evento
// 'finDePartido' del motor real (juego.js). El GUEST nunca corre ese
// motor — se reporta desde motor_online.js, en el mismo punto donde
// ya detecta juegoTerminado sobre el estado espejado recibido.
// ══════════════════════════════════════════════════════════════

// Arma el payload en marco ABSOLUTO host/guest (no relativo jugador/rival):
// si los dos jugaron honesto, el reporte del host y el del guest deben
// coincidir byte a byte pese a partir de perspectivas opuestas de S.
function _netArmarPayloadResultado(puntosJugador, puntosRival, limite) {
  const esHost = NET.rol === "host";
  const puntosHost  = esHost ? puntosJugador : puntosRival;
  const puntosGuest = esHost ? puntosRival   : puntosJugador;
  return {
    puntosHost, puntosGuest, limite,
    ganador: puntosHost > puntosGuest ? "host" : "guest",
  };
}

// Identidad para el RANKING semanal. Va SEPARADA del payload comparado a
// propósito: host y guest tienen nombres distintos, así que meterla adentro
// haría que compararReportes() diera "discrepancia" en TODAS las partidas.
//
// El nombre POR DEFECTO no cuenta como nombre. S.nombreJugador arranca en
// NOMBRE_DEFAULT ("Vos") para todo el que nunca pasó por Ajustes, así que
// mandarlo tal cual llenaba el ranking del grupo de filas "🥇 Vos — 5
// ganadas" — que además de leerse mal junta a varios jugadores distintos
// bajo la misma etiqueta. Mandando "" el server pone "Anónimo", que es lo
// que ya hace con cualquier nombre vacío. La mesa autoritativa ya tenía
// esta defensa (_auto1v1MiNombre en auto1v1_ui.js); esto la trae al relay.
function _netIdentidad() {
  let token;
  try { token = (typeof getDeviceToken === "function") ? getDeviceToken() : undefined; } catch (e) {}
  let nombre = "";
  try {
    // Genérico = el default de hoy o el nombre heredado que se dejó de
    // usar. Si el de S es genérico todavía puede haber uno elegido en
    // localStorage (el lobby del 2v2 lo guarda ahí), así que se prueba
    // antes de rendirse.
    const generico = (n) => !n ||
      (typeof NOMBRE_DEFAULT !== "undefined" && n === NOMBRE_DEFAULT) ||
      (typeof _NOMBRE_HEREDADO !== "undefined" && n === _NOMBRE_HEREDADO);
    const deS = (typeof S !== "undefined" && S.nombreJugador) || "";
    nombre = !generico(deS) ? deS : (localStorage.getItem("truco_nombre") || "");
    if (generico(nombre)) nombre = "";
  } catch (e) { nombre = ""; }
  return { token, nombre: String(nombre).slice(0, 20) };
}

function reportarResultadoOnline(puntosJugador, puntosRival, limite) {
  if (!S.modoOnline || typeof netReportarResultado !== "function") return;
  // En la mesa autoritativa no se reporta nada: el resultado lo dicta el
  // server, que corrió el motor, y ya lo persistió y se lo pasó al ranking
  // y al cuadro de torneo cuando terminó la partida. Mandar además el
  // reporte del relay sería un mensaje que el server descarta (esas salas
  // no tienen `rol`) y que encima podría confundir a quien lea los logs.
  if (S.modoAuto1v1) return;
  netReportarResultado(_netArmarPayloadResultado(puntosJugador, puntosRival, limite), _netIdentidad());
}

// Lado host: juego.js dispara este evento al llegar al límite de puntos.
if (typeof onJuego === "function") {
  onJuego("finDePartido", (payload) => {
    reportarResultadoOnline(payload.puntosJugador, payload.puntosRival, payload.limite);
  });
}


;/* ── amigos.js ── */
// ══════════════════════════════════════════════════════════════
// AMIGOS — pantalla privada para entrar a partidas 1v1 o de torneo
// organizadas por el bot de WhatsApp (ver plan del bot de torneos).
//
// Deliberadamente SEPARADA de "online-screen": acá el código/link
// siempre lo generó el admin del grupo (sala pre-creada server-side,
// nunca el matchmaking público), para no confundir los dos flujos.
//
// Reusa la conexión/protocolo de src/online/netClient.js tal cual
// (mismo servidor, mismo mensaje "unirse") — los handlers globales
// de src/online/juego_online.js (hola, arranque de partida, etc.) ya
// se disparan solos sea cual sea la pantalla que inició la conexión.
// ══════════════════════════════════════════════════════════════

function _amigosMostrarVista(id) {
  ["amigos-menu", "amigos-status"].forEach((v) => {
    const el = document.getElementById(v);
    if (el) el.style.display = v === id ? "flex" : "none";
  });
}

function _amigosSetMsg(id, texto) {
  const el = document.getElementById(id);
  if (el) el.textContent = texto || "";
}

async function amigosUnirseSala(codigoForzado) {
  const btn = document.getElementById("amigos-btn-unirse");
  if (btn && btn.disabled) return; // ya hay un intento de conexión en curso

  const codigo = (codigoForzado || document.getElementById("amigos-codigo-input")?.value || "").trim();
  if (codigo.length < 5) {
    _amigosSetMsg("amigos-menu-msg", "Pegá el código de 5 caracteres que te mandó el admin (o abrí directo su link).");
    return;
  }
  ONLINE.nombre = (document.getElementById("amigos-nombre")?.value || "").trim() || ONLINE.nombre || "Jugador";
  _amigosSetMsg("amigos-menu-msg", "Conectando...");
  // La propia conexión puede tardar "hasta 1 minuto" (server dormido): sin
  // deshabilitar el botón, tocarlo de nuevo en esa espera manda joins
  // duplicados. Se reactiva en el catch de acá y en el listener de "error"
  // (la otra forma en que se vuelve a esta pantalla sin haber conectado).
  if (btn) btn.disabled = true;

  try {
    if (!NET.conectado) {
      const avisar = setTimeout(() => _amigosSetMsg("amigos-menu-msg",
        "Despertando el servidor... puede tardar hasta 1 minuto. Esperá."), 4000);
      try { await netConectar(); } finally { clearTimeout(avisar); }
    }
    netUnirseSala(codigo);
  } catch (e) {
    _amigosSetMsg("amigos-menu-msg", (e && e.message) || "No se pudo conectar al servidor. Probá de nuevo en unos segundos.");
    if (btn) btn.disabled = false;
  }
}

function amigosVolver() {
  netDesconectar();
  if (typeof _onlineResetEstadoPartida === "function") _onlineResetEstadoPartida();
  _amigosMostrarVista("amigos-menu");
  _amigosSetMsg("amigos-menu-msg", "");
  irA("main-menu");
}

// ── Torneos activos ──────────────────────────────────────────────
// Placeholder hasta la Fase 3 del bot (GET /torneo/publico todavía
// no existe en el server).
function amigosCargarTorneos() {
  const cont = document.getElementById("amigos-torneos-lista");
  if (!cont) return;
  cont.innerHTML = '<div class="online-sub">Por ahora no hay torneos activos. Se anuncian en el grupo de WhatsApp.</div>';
}

// ── Deep-link ?sala=XXXX ─────────────────────────────────────────
// Un link mandado por el bot siempre abre Amigos, nunca Online.
// Devuelve true si había un código en la URL y lo manejó (para que el
// boot de anotador.js no pise esto forzando el menú principal).
function _amigosAutoJoinDesdeURL() {
  const params = new URLSearchParams(location.search);
  const codigo = (params.get("sala") || "").trim().toUpperCase();
  if (!codigo) return false;
  history.replaceState(null, "", location.pathname);

  irA("amigos-screen");
  const input = document.getElementById("amigos-codigo-input");
  if (input) input.value = codigo;

  const nombre = (document.getElementById("amigos-nombre")?.value || ONLINE.nombre || "").trim();
  if (nombre) {
    amigosUnirseSala(codigo);
  } else {
    _amigosSetMsg("amigos-menu-msg", "Poné tu nombre arriba y tocá UNIRSE para entrar a la partida.");
  }
  return true;
}

// ── Eventos de red propios de esta pantalla ──────────────────────
// netOn admite varios listeners por evento: estos conviven sin
// pisar los que ya registró juego_online.js para "online-screen".
netOn("sala_creada", (codigo) => {
  _amigosMostrarVista("amigos-status");
  _amigosSetMsg("amigos-status-msg", `🔗 Sala ${codigo} reclamada. Esperando al otro jugador...`);
});
netOn("unido", () => {
  _amigosMostrarVista("amigos-status");
  _amigosSetMsg("amigos-status-msg", "🔗 Conectado. Esperando que arranque la partida...");
});
netOn("rival_conectado", () => {
  _amigosSetMsg("amigos-status-msg", "✅ ¡Conectados los dos! Preparando la partida...");
});
netOn("error", (mensaje) => {
  _amigosMostrarVista("amigos-menu");
  _amigosSetMsg("amigos-menu-msg", mensaje || "Ocurrió un error de conexión.");
  const btn = document.getElementById("amigos-btn-unirse");
  if (btn) btn.disabled = false;
});

document.addEventListener("DOMContentLoaded", () => {
  amigosCargarTorneos();
});


;/* ── apuesta.js ── */
// ══════════════════════════════════════════════════════════════
// APUESTA.JS — Coordinador de partidas TrucoGOL
//
// MODELO: PAGO DIRECTO perdedor → ganador. El organizador NO custodia
// el pozo ni cobra comisión sobre él (eso lo convertiría en "banca" y
// dispara regulación de juego + riesgo de que MP le congele la cuenta).
// La app solo COORDINA: arma la apuesta, anota el resultado y le dice a
// cada perdedor cuánto transferirle directo al ganador.
//
// FLUJO:
//   1. El organizador arma la sala: buy-in por jugador (lo que arriesga
//      cada uno) + jugadores con su alias MP.
//   2. Se juega — TrucoGOL registra el resultado.
//   3. Al terminar: cada PERDEDOR transfiere su buy-in DIRECTO al alias
//      del GANADOR. Aporte al organizador = opcional/voluntario.
// ══════════════════════════════════════════════════════════════

// ─────────────────────────────────────────────────────────────
// CONFIG PERMANENTE DEL ORGANIZADOR
// ─────────────────────────────────────────────────────────────
const CASA = {
  alias:     localStorage.getItem("casa_alias")      || "",
  nombre:    localStorage.getItem("casa_nombre")     || "Truco GOL",
  comision:  parseFloat(localStorage.getItem("casa_comision") || "0"), // aporte OPCIONAL %
};

function casaGuardar() {
  lsSet("casa_alias",     CASA.alias);
  lsSet("casa_nombre",    CASA.nombre);
  lsSet("casa_comision",  CASA.comision);
}

// ─────────────────────────────────────────────────────────────
// PREVIEW DEL POZO
// ─────────────────────────────────────────────────────────────
function casaActualizarPozo() {
  const buyin = parseFloat(document.getElementById("sala-buyin")?.value) || 0;
  const pct   = parseFloat(document.getElementById("casa-comision-inp")?.value) || 0;
  const aporte = Math.round(buyin * pct / 100); // colaboración OPCIONAL, sobre el buy-in

  // Pago DIRECTO: por cada mano se arriesga UN buy-in. Ganás +buy-in del rival,
  // perdés -buy-in. Vale igual en 1v1 y en cada partida de un torneo. No hay
  // "pozo central" (eso sería banca), por eso mostramos el riesgo por jugador.
  const f = v => `$${v.toLocaleString("es-AR")}`;
  _setText("pv-arriesga", f(buyin));
  _setText("pv-gana", `+${f(buyin)}`);
  _setText("pv-pierde", `-${f(buyin)}`);

  const note = document.getElementById("pv-aporte-note");
  if (note) note.style.display = aporte ? "inline" : "none";
  _setText("pv-aporte", f(aporte));
}

function casaTipoChange() { casaActualizarPozo(); }

// ─────────────────────────────────────────────────────────────
// ESTADO DE LA SALA ACTIVA
// ─────────────────────────────────────────────────────────────
const SALA = {
  activa:    false,
  tipo:      "1v1",      // "1v1" | "torneo"
  buyin:     0,          // monto que paga cada jugador
  jugadores: [],         // [{nombre, aliasMP, pago:false}]
  iniciada:  false,      // true cuando todos pagaron y se habilitó jugar
};

// ─────────────────────────────────────────────────────────────
// ABRIR PANEL ORGANIZADOR (reemplaza modales anteriores)
// ─────────────────────────────────────────────────────────────
function casaAbrirPanel(modo) {
  // Pre-seleccionar tipo si viene del menú
  if (modo) {
    const sel = document.getElementById("sala-tipo");
    if (sel) {
      if (modo === "1v1")    sel.value = "1v1";
      if (modo === "torneo") sel.value = "torneo4";
    }
  }
  _casaRellenar();
  document.getElementById("casa-modal")?.classList.add("show");
}
function casaCerrar() {
  document.getElementById("casa-modal")?.classList.remove("show");
}

function _casaRellenar() {
  const inpAlias  = document.getElementById("casa-alias-inp");
  const inpNombre = document.getElementById("casa-nombre-inp");
  const inpCom    = document.getElementById("casa-comision-inp");
  if (inpAlias)  inpAlias.value  = CASA.alias;
  if (inpNombre) inpNombre.value = CASA.nombre;
  if (inpCom)    inpCom.value    = CASA.comision;
  _casaRenderJugadores();
  _casaActualizarEstado();
  casaActualizarPozo();

  // Mostrar/ocultar botón cerrar sala
  const btnCerrar = document.getElementById("btn-cerrar-sala");
  if (btnCerrar) btnCerrar.style.display = SALA.activa ? "block" : "none";
}

function casaGuardarConfig() {
  CASA.alias    = (document.getElementById("casa-alias-inp")?.value  || "").trim();
  CASA.nombre   = (document.getElementById("casa-nombre-inp")?.value || "").trim() || "Truco GOL";
  CASA.comision = parseFloat(document.getElementById("casa-comision-inp")?.value) || 0;
  casaGuardar();
  casaActualizarPozo();
  showToast("✅ Datos del organizador guardados", 1600);
}

// ─────────────────────────────────────────────────────────────
// GESTIÓN DE JUGADORES EN LA SALA
// ─────────────────────────────────────────────────────────────
function casaAgregarJugador() {
  const nombre = (document.getElementById("sala-j-nombre")?.value || "").trim();
  const alias  = (document.getElementById("sala-j-alias")?.value  || "").trim();
  if (!nombre) { showToast("Ingresá el nombre", 1400); return; }
  if (SALA.jugadores.length >= 8) { showToast("Máximo 8 jugadores", 1400); return; }
  if (SALA.jugadores.find(j => j.nombre === nombre)) {
    showToast("Ya existe ese jugador", 1400); return;
  }
  SALA.jugadores.push({ nombre, aliasMP: alias, pago: false });
  const inpN = document.getElementById("sala-j-nombre");
  const inpA = document.getElementById("sala-j-alias");
  if (inpN) inpN.value = "";
  if (inpA) inpA.value = "";
  if (inpN) inpN.focus(); // listo para tipear el siguiente
  _casaRenderJugadores();
  _casaActualizarEstado();
}

function casaQuitarJugador(idx) {
  SALA.jugadores.splice(idx, 1);
  _casaRenderJugadores();
}

function casaTogglePago(idx) {
  SALA.jugadores[idx].pago = !SALA.jugadores[idx].pago;
  _casaRenderJugadores();
  _casaActualizarEstado();
}

function _casaRenderJugadores() {
  const lista = document.getElementById("sala-lista");
  if (!lista) return;
  if (SALA.jugadores.length === 0) {
    lista.innerHTML = `<div class="sa-empty">Agregá los jugadores de esta partida</div>`;
    return;
  }
  lista.innerHTML = SALA.jugadores.map((j, i) => `
    <div class="sa-jugador ${j.pago ? 'pagado' : 'pendiente'}">
      <div class="sa-jugador-info">
        <span class="sa-jugador-nombre">${esc(j.nombre)}${esMoroso(j) ? ` <span class="sa-moroso" title="Quedó debiendo en una partida anterior">⚠️ MOROSO</span>` : ""}</span>
        ${j.aliasMP ? `<span class="sa-jugador-alias">💳 @${esc(j.aliasMP)}</span>` : ""}
      </div>
      <button class="sa-pago-btn ${j.pago ? 'confirmado' : ''}"
              onclick="casaTogglePago(${i})"
              title="${j.pago ? 'Marcar como NO confirmado' : 'Confirmar que este jugador entra a la apuesta'}">
        ${j.pago ? "✅ ADENTRO" : "⏳ CONFIRMAR"}
      </button>
      ${!SALA.iniciada ? `<button class="g-quitar" onclick="casaQuitarJugador(${i})">✕</button>` : ""}
    </div>`).join("");

  // Resumen: cuántos confirmaron que juegan y el pozo total en juego.
  const confirmados = SALA.jugadores.filter(j => j.pago).length;
  const total       = SALA.jugadores.length;
  const pot         = total * SALA.buyin;
  const resumen     = document.getElementById("sala-resumen");
  if (resumen) {
    resumen.innerHTML = `
      <span class="${confirmados === total ? 'ok' : 'warn'}">
        ${confirmados}/${total} confirmados
      </span>
      <span class="pot">💰 En juego: $${pot.toLocaleString("es-AR")}</span>`;
  }
}

function _casaActualizarEstado() {
  const btnIniciar  = document.getElementById("sala-btn-iniciar");
  const btnCompartir = document.getElementById("sala-btn-compartir");
  if (!btnIniciar || !btnCompartir) return;

  const todosPagaron = SALA.jugadores.length >= 2 &&
                       SALA.jugadores.every(j => j.pago);

  btnIniciar.disabled   = !todosPagaron || SALA.iniciada;
  btnCompartir.disabled = SALA.jugadores.length < 1 || SALA.buyin <= 0;
}

// ─────────────────────────────────────────────────────────────
// CREAR SALA
// ─────────────────────────────────────────────────────────────
function casaCrearSala() {
  const buyin = parseFloat(document.getElementById("sala-buyin")?.value) || 0;
  if (buyin <= 0) { showToast("Ingresá el monto del buy-in", 1600); return; }
  // El alias del organizador ya NO es obligatorio: la plata va directo al
  // ganador, no a Chucho. Solo hace falta el alias de cada jugador.

  SALA.activa    = true;
  SALA.iniciada  = false;
  SALA.buyin     = buyin;
  SALA.tipo      = document.getElementById("sala-tipo")?.value || "1v1";
  SALA.comision  = parseFloat(document.getElementById("casa-comision-inp")?.value) || CASA.comision;
  SALA.jugadores = [];
  SALA.bracket   = [];  // para torneos

  _casaRenderJugadores();
  _casaActualizarEstado();
  showToast(`✅ Sala creada — $${buyin} buy-in`, 1600);
  _casaBadgeActualizar();

  // Mostrar sección de bracket si es torneo
  const brackets = document.getElementById("torneo-bracket-section");
  if (brackets) brackets.style.display = SALA.tipo !== "1v1" ? "block" : "none";
}

function casaCerrarSala() {
  SALA.activa   = false;
  SALA.iniciada = false;
  SALA.jugadores = [];
  SALA.bracket   = [];
  _casaBadgeActualizar();
  casaCerrar();
  showToast("Sala cerrada", 1400);
}

// ─────────────────────────────────────────────────────────────
// COMPARTIR INSTRUCCIONES DE PAGO por WhatsApp
// ─────────────────────────────────────────────────────────────
function casaCompartirInstrucciones() {
  if (SALA.buyin <= 0) { showToast("Configurá el buy-in primero", 1600); return; }

  const nombres = SALA.jugadores.map(j => `• ${j.nombre}`).join("\n") || "• (jugadores por confirmar)";
  const msg =
`🎴⚽ *TRUCO GOL — Convocatoria*
━━━━━━━━━━━━━━━
📋 Jugadores:
${nombres}
━━━━━━━━━━━━━━━
💰 Apuesta: *$${SALA.buyin.toLocaleString("es-AR")} por cabeza*
━━━━━━━━━━━━━━━
💸 *Cómo se paga:* el que pierde le transfiere
$${SALA.buyin.toLocaleString("es-AR")} *directo al ganador* (a su alias MP).
Nadie paga por adelantado a un tercero.
━━━━━━━━━━━━━━━
🏆 Ganador se lleva todo el pozo de los perdedores.
Partida registrada en *Truco GOL*. 🎴⚽`;

  const url = `https://wa.me/?text=${encodeURIComponent(msg)}`;
  window.open(url, "_blank", "noopener");
}

// Compartir instrucción individual a un jugador específico
function casaCompartirAJugador(idx) {
  const j = SALA.jugadores[idx];
  if (!j) return;

  const msg =
`🎴 *TRUCO GOL — ${j.nombre}, quedás anotado*
Apuesta: *$${SALA.buyin.toLocaleString("es-AR")} por cabeza*.
💸 Si perdés, le transferís ese monto *directo al ganador*.
Si ganás, cada perdedor te paga a vos.
${j.aliasMP ? `Tu alias MP cargado: *${j.aliasMP}*` : "⚠️ Pasame tu alias MP para poder anotarlo."}
¡Nos vemos en la mesa! ⚽`;

  const url = `https://wa.me/?text=${encodeURIComponent(msg)}`;
  window.open(url, "_blank", "noopener");
}

// ─────────────────────────────────────────────────────────────
// INICIAR PARTIDA (todos pagaron)
// ─────────────────────────────────────────────────────────────
function casaIniciarPartida() {
  const todosPagaron = SALA.jugadores.every(j => j.pago);
  if (!todosPagaron) { showToast("⚠️ Hay pagos pendientes", 1800); return; }
  SALA.iniciada = true;
  casaCerrar();
  showToast(`🎯 ¡A jugar! Cada mano vale $${SALA.buyin.toLocaleString("es-AR")} — pago directo al ganador`, 2800);
  _casaBadgeActualizar();
}

// ─────────────────────────────────────────────────────────────
// LEDGER DE MOROSOS — la única defensa real contra el que no paga.
// Como la app no puede FORZAR el pago (es P2P), lo que hace es dejar
// marcado por alias/nombre a quien quedó debiendo. Ese ⚠️ MOROSO le
// aparece la próxima vez que lo agregan a una sala: castigo social.
// ─────────────────────────────────────────────────────────────
const MOROSOS_KEY = "tg_morosos";
function _morosoKey(j)  { return ((j.aliasMP || j.nombre) || "").trim().toLowerCase(); }
function _morososGet()  { try { return JSON.parse(localStorage.getItem(MOROSOS_KEY) || "{}"); } catch (_) { return {}; } }
function _morososSave(m) { try { localStorage.setItem(MOROSOS_KEY, JSON.stringify(m)); } catch (_) {} }
function esMoroso(j)    { return !!_morososGet()[_morosoKey(j)]; }
function marcarMoroso(j, debe) {
  const m = _morososGet(), k = _morosoKey(j);
  if (!k) return;
  if (debe) m[k] = { nombre: j.nombre, alias: j.aliasMP || "", desde: Date.now() };
  else      delete m[k];
  _morososSave(m);
}

// Renderiza en el overlay de resultado la lista de perdedores con un
// toggle "✅ pagó / ⚠️ me debe" por cada uno.
function _casaRenderCobros(perdedorObj) {
  const cont = document.getElementById("cp-cobros");
  if (!cont) return;
  // Pago directo: en cada partida hay UN solo perdedor (el rival) que le
  // transfiere el buy-in al ganador. Antes listaba a TODOS los no-ganadores,
  // lo que en un torneo mostraba deudores que no jugaron esa partida.
  const perdedores = (perdedorObj && perdedorObj.nombre) ? [perdedorObj] : [];
  if (!perdedores.length) { cont.innerHTML = ""; return; }

  cont.innerHTML = `<div class="cp-cobros-tit">¿Quién ya te pagó?</div>` +
    perdedores.map(j => {
      const idx  = SALA.jugadores.indexOf(j);
      const debe = esMoroso(j);
      return `<div class="cp-cobro-row ${debe ? "debe" : ""}">
        <span class="cp-cobro-nombre">${esc(j.nombre)}${j.aliasMP ? ` <span class="cp-cobro-alias">@${esc(j.aliasMP)}</span>` : ""}</span>
        <button class="cp-cobro-btn ${debe ? "rojo" : "ok"}" onclick="casaToggleCobro(${idx})">
          ${debe ? "⚠️ ME DEBE" : "✅ PAGÓ"}
        </button>
      </div>`;
    }).join("");
}

function casaToggleCobro(idx) {
  const j = SALA.jugadores[idx];
  if (!j) return;
  marcarMoroso(j, !esMoroso(j)); // toggle: pagó ↔ me debe
  const modal = document.getElementById("casa-pago-modal");
  // _casaRenderCobros espera el OBJETO del perdedor, no el nombre del
  // ganador: pasarle el string hacía que la lista de cobros desapareciera
  // apenas marcabas uno y no se podía seguir marcando.
  _casaRenderCobros(modal ? modal._perdedorObj : null);
}

// ─────────────────────────────────────────────────────────────
// RESULTADO — dónde transferir al ganador
// ─────────────────────────────────────────────────────────────
// Resuelve ganador/perdedor por POSICIÓN en la sala, no por string frágil
// (antes, si S.nombreJugador no matcheaba EXACTO una entrada, mostraba el alias
// MP equivocado → plata al que no ganó). El jugador local es el que matchea su
// nombre, o el asiento 0 si no matchea (el organizador suele ser el local). En
// 1v1 el rival es el otro asiento, sin ambigüedad. Devuelve objetos reales de
// la sala (con su aliasMP), nunca un fantasma.
function _casaGanadorPerdedor(nombreJ, ganoJ) {
  const js = SALA.jugadores || [];
  const norm = s => ((s || "") + "").trim().toLowerCase();
  let idxLocal = js.findIndex(j => norm(j.nombre) === norm(nombreJ));
  if (idxLocal < 0) idxLocal = 0;
  let idxRival;
  if (js.length === 2) idxRival = idxLocal === 0 ? 1 : 0;
  else idxRival = js.findIndex((j, i) => i !== idxLocal);
  const local = js[idxLocal] || {}, rival = js[idxRival] || {};
  // En salas de 3+ el "rival" es el primer asiento distinto del local, NO
  // necesariamente el que jugó esta partida: la sala no guarda con quién se
  // jugó. Se marca como ambiguo para no afirmar un alias que puede mandar
  // la plata a la persona equivocada (ver casaMostrarPago).
  const ambiguo = js.length > 2;
  return ganoJ ? { ganadorObj: local, perdedorObj: rival, ambiguo }
               : { ganadorObj: rival, perdedorObj: local, ambiguo };
}

function casaMostrarPago(ptsJ, ptsR) {
  if (!SALA.activa || !SALA.iniciada) return;

  const modal = document.getElementById("casa-pago-modal");
  if (!modal) return;

  // Modelo del app (ver convocatoria): pago DIRECTO por partida — el que
  // pierde ESA partida le transfiere UN buy-in al que ganó, nada de pozo
  // central ni "todos le pagan al campeón". Vale igual para 1v1 y para cada
  // partida de un torneo.
  const pct         = (SALA.comision ?? CASA.comision) || 0;
  const aporte      = Math.round(SALA.buyin * pct / 100);         // opcional, sobre el buy-in transferido
  const recibe      = SALA.buyin;                                 // un buy-in, del rival de esta partida
  const ganoJugador = ptsJ > ptsR;

  const nombreJ = (typeof S !== "undefined" ? S.nombreJugador : "Jugador") || "Jugador";
  const { ganadorObj: gObj, perdedorObj: pObj, ambiguo } = _casaGanadorPerdedor(nombreJ, ganoJugador);
  const ganadorNombre = (gObj && gObj.nombre) || "Rival";
  const ganadorObj = (gObj && gObj.nombre) ? gObj : null;
  const perdedores  = 1;                                          // un solo rival por partida

  _setText("cp-marcador", `${ptsJ} - ${ptsR}`);
  _setText("cp-ganador",  ganadorNombre);
  _setText("cp-pot",      `$${recibe.toLocaleString("es-AR")}`);
  _setText("cp-comision", aporte ? `$${aporte.toLocaleString("es-AR")} (opc.)` : "—");

  const aliasEl = document.getElementById("cp-alias");
  const btnMP   = document.getElementById("cp-btn-mp");
  if (ambiguo && !ganoJugador) {
    // Perdiste en una mesa de 3+: el "ganador" que dedujimos puede no ser
    // quien jugó contra vos. No mostramos alias ni botón de transferencia
    // para no mandarle la plata a otro.
    aliasEl.textContent   = "⚠️ Mesa de más de 2 jugadores: confirmá con el organizador a quién le transferís antes de pagar.";
    aliasEl.style.display = "block";
    if (btnMP) btnMP.style.display = "none";
  } else if (ganadorObj?.aliasMP) {
    // Cada perdedor le transfiere el buy-in a ESTE alias (el del ganador).
    aliasEl.textContent   = `💳 ${perdedores} perdedor(es) transfieren $${SALA.buyin.toLocaleString("es-AR")} c/u a: ${ganadorObj.aliasMP}`;
    aliasEl.style.display = "block";
    if (btnMP) {
      btnMP.style.display = "block";
      btnMP.onclick = () => window.open(`https://mpago.la/${ganadorObj.aliasMP}`, "_blank", "noopener");
    }
  } else {
    aliasEl.textContent   = "⚠️ El ganador no tiene alias MP cargado — pídanselo para cobrar.";
    aliasEl.style.display = "block";
    if (btnMP) btnMP.style.display = "none";
  }

  modal._ganador  = ganadorNombre;
  modal._perdedorObj = pObj || null; // lo re-usa casaToggleCobro
  modal._pot      = recibe;
  modal._comision = aporte;
  modal._alias    = ganadorObj?.aliasMP || "";
  modal._buyin    = SALA.buyin;

  // Ledger: quién le debe al ganador de ESTA partida (solo su rival).
  _casaRenderCobros(pObj);

  // Registrar en bracket si es torneo
  if (SALA.tipo !== "1v1") {
    _torneoRegistrarResultado(ganoJugador ? nombreJ : ganadorNombre,
                              ganoJugador ? ganadorNombre : nombreJ);
    _torneoRenderBracket();
  }

  modal.classList.add("show");
}

function casaPagoCerrar() {
  document.getElementById("casa-pago-modal")?.classList.remove("show");
}

function casaCompartirPago() {
  const modal = document.getElementById("casa-pago-modal");
  if (!modal) return;
  const { _ganador, _pot, _comision, _alias, _buyin } = modal;
  const pagoLinea  = _alias
    ? `\n💸 El perdedor transfiere *$${(_buyin||0).toLocaleString("es-AR")}* a: *${_alias}*`
    : `\n💸 El perdedor le paga *$${(_buyin||0).toLocaleString("es-AR")}* al ganador.`;
  const aporteLinea = _comision ? `\n🤝 Aporte al organizador (opcional): $${(_comision||0).toLocaleString("es-AR")}` : "";
  const msg =
`🏆 *TRUCO GOL — Resultado Oficial*
━━━━━━━━━━━━━━━
🥇 Ganador: *${_ganador}*
💰 Recibe en total: *$${(_pot||0).toLocaleString("es-AR")}*${pagoLinea}${aporteLinea}
━━━━━━━━━━━━━━━
La plata va directo perdedor → ganador.
Partida registrada en *Truco GOL* 🎴⚽`;

  const url = `https://wa.me/?text=${encodeURIComponent(msg)}`;
  window.open(url, "_blank", "noopener");
}

// ─────────────────────────────────────────────────────────────
// BRACKET DE TORNEO
// ─────────────────────────────────────────────────────────────
function _torneoRegistrarResultado(ganador, perdedor) {
  if (!SALA.bracket) SALA.bracket = [];
  SALA.bracket.push({ ganador, perdedor, ts: Date.now() });
}

function _torneoRenderBracket() {
  const el = document.getElementById("torneo-bracket");
  if (!el || !SALA.bracket?.length) return;
  el.innerHTML = SALA.bracket.map((r, i) => `
    <div style="display:flex;align-items:center;gap:8px;padding:6px 0;
                border-bottom:1px solid rgba(255,255,255,.06);font-size:12px;">
      <span style="color:rgba(255,255,255,.4);font-size:10px;width:20px;">P${i+1}</span>
      <span style="color:#27ae60;font-weight:bold;">🏆 ${r.ganador}</span>
      <span style="color:rgba(255,255,255,.3);">vs</span>
      <span style="color:#e74c3c;">❌ ${r.perdedor}</span>
    </div>`).join("");
}

function casaCompartirBracket() {
  if (!SALA.bracket?.length) { showToast("No hay partidas registradas aún", 1400); return; }
  const lineas = SALA.bracket.map((r, i) => `P${i+1}: 🏆 ${r.ganador} vs ❌ ${r.perdedor}`);
  const n      = SALA.tipo === "torneo6" ? 6 : 4;
  const msg =
`🎴 *TRUCO GOL — Bracket Torneo ${n} jugadores*
Buy-in: $${SALA.buyin.toLocaleString("es-AR")} c/u
━━━━━━━━━━━━━━━
${lineas.join("\n")}
━━━━━━━━━━━━━━━
🏠 Organizador: *${CASA.nombre}*
Supervisado en *Truco GOL* 🎴⚽`;

  const url = `https://wa.me/?text=${encodeURIComponent(msg)}`;
  window.open(url, "_blank", "noopener");
}

// ─────────────────────────────────────────────────────────────
// BADGE y helpers UI
// ─────────────────────────────────────────────────────────────
function _casaBadgeActualizar() {
  const badge = document.getElementById("casa-badge");
  if (!badge) return;
  if (!SALA.activa) { badge.style.display = "none"; return; }
  const pagados = SALA.jugadores.filter(j => j.pago).length;
  const total   = SALA.jugadores.length;
  const pot     = pagados * SALA.buyin;
  badge.style.display = "flex";
  badge.innerHTML = SALA.iniciada
    ? `🎯 $${pot.toLocaleString("es-AR")} en juego`
    : `💰 ${pagados}/${total} pagaron`;
}

