      var esActual   = cap.id === actual;
      var bloqueado  = cap.id > actual;
      var victoria   = victorias.indexOf(cap.id) !== -1;

      var estadoClass = bloqueado ? 'bloqueado' : (completado ? 'completado' : (esActual ? 'actual' : ''));
