  // Notificación propia para logros extra (usa la del sistema si está disponible)
  function _desbloquearLogroExtra(id) {
    // OJO: acá NO se llama a window.desbloquearLogro. Desde el 2-ago-2026
    // esa función delega los ids que no conoce en ESTA — llamarla de vuelta
    // sería recursión infinita. El ruteo va en un solo sentido:
    // desbloquearLogro (los 8 clásicos) → _desbloquearLogroExtra (los 16).
    var desbloqueados = lsGetJSON('tg_logros_extra', []);
    if (desbloqueados.indexOf(id) !== -1) return;

    var def = LOGROS_EXTRA.find(function(l) { return l.id === id; });
    if (!def) { console.warn('[logros] id inexistente en LOGROS_EXTRA:', id); return; }

    desbloqueados.push(id);
    lsPutJSON('tg_logros_extra', desbloqueados);

    // Mostrar notificación
    _mostrarNotifLogroExtra(def);
  }

  function _mostrarNotifLogroExtra(def) {
    // Si el sistema de extras.js ya mostró notif, no duplicar
    // Usamos un div con ID propio
    var notif = document.getElementById('hist-logro-notif');
    if (!notif) {
      notif = document.createElement('div');
      notif.id = 'hist-logro-notif';
      // Anclado ARRIBA a propósito: abajo (bottom:80px) caía justo sobre
      // la barra de acciones y tapaba ENVIDO / REAL / FALTA en el momento
      // exacto en que hay que elegir. Un logro es informativo; nunca
      // puede robarle la pantalla a una decisión.
      notif.style.cssText = 'position:fixed;top:14px;left:50%;transform:translateX(-50%) translateY(-160px);background:linear-gradient(135deg,#1a2a0a,#0a1a0a);border:1px solid #7ed856;border-radius:12px;padding:12px 16px;display:flex;align-items:center;gap:10px;z-index:3000;transition:transform 0.4s cubic-bezier(0.34,1.56,0.64,1);pointer-events:none;min-width:280px;max-width:90vw;';
      notif.innerHTML = '<div id="hist-logro-notif-ico" style="font-size:28px"></div>' +
        '<div><div style="font-family:var(--f-ui,monospace);font-size:9px;letter-spacing:2px;color:#5a9e45;margin-bottom:2px">¡LOGRO EXTRA!</div>' +
        '<div id="hist-logro-notif-nom" style="font-family:var(--f-ui,monospace);font-size:12px;font-weight:bold;color:#c8f0a0;letter-spacing:1px"></div>' +
        '<div id="hist-logro-notif-des" style="font-family:var(--f-body,serif);font-size:10px;color:#7ed856;margin-top:2px"></div></div>';
      document.body.appendChild(notif);
    }

    document.getElementById('hist-logro-notif-ico').textContent = def.ico;
    document.getElementById('hist-logro-notif-nom').textContent = def.nombre;
    document.getElementById('hist-logro-notif-des').textContent = def.desc;
    notif.style.transform = 'translateX(-50%) translateY(0)';

    setTimeout(function() {
      notif.style.transform = 'translateX(-50%) translateY(-160px)';
    }, 4000);
  }

  // Chequeos automáticos de logros extra
  function _checkLogrosHistoria() {
    // `victorias`, NO `completados`: un capítulo entra en `completados` se
    // gane o se pierda (ver el handler de finDePartido), así que perder el
    // capítulo 1 desbloqueaba "Completaste el capítulo 1". Los tres textos
    // dicen "Completaste", que en un modo campaña significa ganarlo.
    var ganados = (_historiaState.victorias || []).length;
    if (ganados >= 1)  _desbloquearLogroExtra('historia_1');
    if (ganados >= 5)  _desbloquearLogroExtra('historia_5');
    if (ganados >= 10) _desbloquearLogroExtra('historia_10');
  }

  function _hookLogrosExtra() {
    if (typeof onJuego !== 'function') return;

    // tg_racha_abs y NO tg_racha: la racha de partidos la persiste este
    // mismo hook en tg_racha_abs, pero al recargar se sembraba con tg_racha,
    // que es la racha de MANOS de extras.js — la racha real de 10 partidos
    // se perdía (o se inflaba) en cada recarga.
    var _partidasConsecutivas = parseInt(lsGet('tg_racha_abs', '0'), 10) || 0;
    var _manosJugadasPartida  = 0;

    // Manos REALES del partido: S.ganadoresRonda son las rondas de UNA mano
    // (máximo 3, se resetea en cada reparto), así que el logro 'velocista'
    // ("ganar en pocas manos") se regalaba en la primera victoria.
    onJuego('manoRepartida', function() { _manosJugadasPartida++; });

    onJuego('nuevoPartido', function() {
      _manosJugadasPartida  = 0;
      // Chequear hora para logros de horario
      var hora = new Date().getHours();
      // getHours() devuelve 0..23: el `hora >= 24` de antes era una
      // condición muerta, y con `hora < 8` el que jugaba a las 2 de la
      // mañana se llevaba "Madrugador" en vez de "El Búho". Se reparte la
      // noche: 0-4 es trasnochar, 5-7 es madrugar.
      if (hora >= 5 && hora < 8) _desbloquearLogroExtra('madrugador');
      if (hora < 5)              _desbloquearLogroExtra('nocturno');
    });

    // (Acá había un handler de 'render' que contaba manos con
    // S.ganadoresRonda. Era el conteo VIEJO y equivocado —ganadoresRonda son
    // las rondas de UNA mano, no las manos del partido— y quedó sin lectores
    // cuando el logro 'velocista' pasó a usar _manosJugadasPartida. Corría en
    // cada render del juego para calcular un número que ya no miraba nadie.)

    onJuego('finDePartido', function(data) {
      if (!data) return;
      var ganamos = data.puntosJugador >= (data.limite || 30);

      // Total partidas (para 'fiel')
      var total = parseInt(lsGet('tg_partidas_total_g', '0'), 10) + 1;
      lsPut('tg_partidas_total_g', total);
      if (total >= 50) _desbloquearLogroExtra('fiel');

      if (ganamos) {
        // Racha para 'sin_derrota'
        _partidasConsecutivas++;
        lsPut('tg_racha_abs', _partidasConsecutivas);
        if (_partidasConsecutivas >= 10) _desbloquearLogroExtra('sin_derrota');

        // 30-0
        if (data.puntosRival === 0 && data.puntosJugador >= (data.limite || 30)) {
          _desbloquearLogroExtra('30_cero');
        }

        // Velocista: ganó en pocas MANOS de verdad (ver 'manoRepartida').
        if (_manosJugadasPartida > 0 && _manosJugadasPartida <= 5) {
          _desbloquearLogroExtra('velocista');
        }

        // Hora nocturna — mismo criterio que en 'nuevoPartido' (0-4 es
        // trasnochar, 5-7 es madrugar). Acá había otra copia del `hora >= 24`
        // muerto, y otra vez `hora < 8` le daba "Madrugador" al que jugaba
        // a las 2 de la mañana.
        var hora = new Date().getHours();
        if (hora < 5)              _desbloquearLogroExtra('nocturno');
        if (hora >= 5 && hora < 8) _desbloquearLogroExtra('madrugador');
      } else {
        _partidasConsecutivas = 0;
        lsPut('tg_racha_abs', 0);
      }
    });
  }

  function setupLogrosExtra() {
    _hookLogrosExtra();
    // La exposición global va toda junta al final del archivo (antes esto
    // re-asignaba desbloquearLogroExtra y LOGROS_EXTRA por segunda vez, y
    // encima solo si esta función llegaba a correr).
  }

