  // ─────────────────────────────────────────────────────────────
  // INIT
  // ─────────────────────────────────────────────────────────────
  function init() {
    try { setupAdaptativo(); } catch (e) { console.warn('[adaptive] adaptativo:', e); }
    try { setupFrases();     } catch (e) { console.warn('[adaptive] frases:', e); }
  }

